async function analyzeImageDataUrl(
  dataUrl,
  prompt = ""
) {
  const imageInput = String(dataUrl || "").trim();
  if (
    !imageInput ||
    (!isInlineImageData(imageInput) && !/^https:\/\//i.test(imageInput))
  ) {
    return "";
  }

  const result = await apiJson("/ai/vision", {
    method: "POST",
    body: JSON.stringify({
      provider: DEFAULT_AI_PROVIDER,
      model: DEFAULT_AI_MODEL,
      image: imageInput,
      prompt:
        prompt ||
        "Describe what is visibly happening in this image in 1-3 concise sentences. Mention people, clothing, activity, location and mood only when visible. Do not identify real people by name.",
    }),
  });

  return String(
    (result && result.text) || ""
  )
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 700);
}

async function requestAiImageProxy(payload) {
  const paths = ["/ai/image", "/ai/images", "/ai/generate-image"];
  const urls = paths.map(backendUrl);

  if (isLocalDevBrowser()) {
    const host = window.location.hostname || "127.0.0.1";
    paths.forEach((path) => urls.push(`http://${host}:3000${path}`));
  }

  let lastErr = null;

  for (const url of [...new Set(urls)]) {
    try {
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(payload),
      });

      let data = null;
      try { data = await res.json(); } catch (e) { data = null; }

      if (res.ok) return data;
      if (res.status !== 404) {
        const err = new Error(
          (data && data.error && (data.error.message || data.error)) ||
          (data && data.error) ||
          `HTTP ${res.status}`
        );
        err.status = res.status;
        throw err;
      }
      lastErr = new Error(`HTTP ${res.status}`);
      lastErr.status = 404;
    } catch (err) {
      lastErr = err;

      /*
       * A real backend/image-provider error is authoritative. Do NOT fan the
       * same expensive image request out to every alias, because that can
       * multiply rate limits and costs. Only 404/network discovery failures
       * are allowed to fall through to the next candidate URL.
       */
      if (err && Number(err.status) && Number(err.status) !== 404) {
        throw err;
      }
    }
  }

  if (lastErr && Number(lastErr.status) !== 404) {
    console.warn("AI image proxy unavailable:", lastErr);
  }
  return null;
}

function bestAlbumSnapFallback(character, prompt) {
  const items = albumOf(character);
  if (!items.length) return null;

  const terms = normUtterance(prompt)
    .split(" ")
    .filter((word) => word.length >= 4);
  if (!terms.length) return null;

  let best = null;
  let bestScore = 0;

  items.forEach((item) => {
    if (!item) return;
    const hay = normUtterance(`${item.note || ""} ${item.vision || ""}`);
    let score = 0;
    terms.forEach((term) => { if (hay.includes(term)) score += 1; });
    if (score > bestScore) { bestScore = score; best = item; }
  });

  return bestScore >= 1 ? best : null;
}

function chatExplicitlyRequestsImage(text) {
  const t = String(text || "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();

  if (!t) return false;

  return /(?:küldj|küldenél|küldesz|mutass|dobj át|dobd át|kérek|akarok|szeretnék|send|show|lemme see|let me see|can i see|could i see|give me|drop)\b[^.!?]{0,70}\b(?:kép|képet|fotó|fotót|selfie|szelfi|snap|pic|picture|photo|image)|\b(?:kép|képet|fotó|fotót|selfie|szelfi|snap|pic|picture|photo|image)\b[^.!?]{0,60}\b(?:küld|send|show|please|pls|plz)/i.test(t);
}

function forcedChatSnapPrompt(playerText, character) {
  return `Create the exact kind of current private-chat snap requested by the player: "${cut(String(playerText || ""), 220)}". The sender is ${(character && character.name) || "the character"}. Keep it realistic, current, casual, character-faithful and visually consistent with the request. Do not invent extra people or events unless the request or current context requires them.`;
}

function appendAiChatImageMessage(n, characterId, snap) {
  if (!n || !characterId || !snap || !(snap.imageId || snap.image)) return false;
  const ck = chatKey(n.meId, characterId);
  n.chats[ck] = [
    ...(n.chats[ck] || []),
    {
      id: "dm_" + uid(),
      from: "them",
      to: n.meId,
      text: "",
      ts: now(),
      imageId: snap.imageId || "",
      image: snap.imageId ? "" : (snap.image || ""),
      imageDescription: snap.imageDescription || "",
      language: worldLanguage(n, n.meId),
    },
  ];
  return true;
}

const SNAP_VISUAL_IDENTITY_CACHE = new Map();

async function describeCharacterReferenceImage(ref, media, prompt) {
  const resolved = String(resolveImg(ref, media) || "").trim();
  if (
    !resolved ||
    (!isInlineImageData(resolved) && !/^https:\/\//i.test(resolved))
  ) return "";
  const key = String(ref || resolved).slice(0, 180);
  if (SNAP_VISUAL_IDENTITY_CACHE.has(key)) {
    return SNAP_VISUAL_IDENTITY_CACHE.get(key) || "";
  }
  try {
    const desc = await analyzeImageDataUrl(
      resolved,
      prompt || "Describe the main person's stable visible appearance in 1-3 concise sentences for identity-consistent image generation. Focus on face shape, hair, coloring, age vibe and other stable traits only."
    );
    const clean = cut(String(desc || "").replace(/\s+/g, " ").trim(), 320);
    SNAP_VISUAL_IDENTITY_CACHE.set(key, clean);
    return clean;
  } catch (err) {
    console.warn("Character reference image analysis failed:", err);
    SNAP_VISUAL_IDENTITY_CACHE.set(key, "");
    return "";
  }
}

async function buildCharacterSnapIdentity(character, media) {
  if (!character) return "";

  const parts = [];
  const seen = new Set();
  const pushUnique = (label, value) => {
    const clean = cut(String(value || "").replace(/\s+/g, " ").trim(), 320);
    if (!clean) return;
    const key = normUtterance(clean);
    if (!key || seen.has(key)) return;
    seen.add(key);
    parts.push(`${label}: ${clean}`);
  };

  pushUnique("Written looks", character.looks || character.bio || "");

  const avatarDesc = await describeCharacterReferenceImage(
    character.avatar,
    media,
    `Describe the stable visible appearance of the main person in this profile image for identity-consistent image generation. Focus on face shape, hair style/color, complexion, age vibe and other stable traits. Mention clothing only if it seems identity-defining.`
  );
  pushUnique("Profile photo appearance", avatarDesc);

  const album = albumOf(character).slice(0, 4);
  for (const item of album) {
    if (!item) continue;
    pushUnique("Album appearance hint", item.vision || item.note || "");
    if (!(item.vision || item.note)) {
      const ref = item.imageId ? imageRef(item.imageId) : (item.src || item.image || "");
      const itemDesc = await describeCharacterReferenceImage(
        ref,
        media,
        `Describe the main person's visible appearance and vibe in this character album image for identity-consistent image generation. Focus on stable face/hair/build traits first, then scene briefly.`
      );
      pushUnique("Album appearance hint", itemDesc);
    }
    if (parts.length >= 5) break;
  }

  return cut(parts.join("\n"), 1200);
}

function characterSnapReferenceImages(character, media, limit = 3) {
  if (!character) return [];
  const refs = [];
  const add = (ref) => {
    if (!ref || refs.length >= limit) return;
    const resolved = String(resolveImg(ref, media) || "").trim();
    if (
      !resolved ||
      (!isInlineImageData(resolved) && !/^https:\/\//i.test(resolved))
    ) {
      return;
    }
    if (!refs.includes(resolved)) refs.push(resolved);
  };
  add(character.avatar);
  for (const item of albumOf(character)) {
    if (refs.length >= limit) break;
    if (!item) continue;
    add(item.imageId ? imageRef(item.imageId) : (item.src || item.image || ""));
  }
  return refs;
}

function albumIntentToGeneratedSnapPrompt(character, item, fallbackPrompt = "") {
  if (!item) return String(fallbackPrompt || "").trim();
  const visible = String(item.vision || item.note || "").replace(/\s+/g, " ").trim();
  return `Generate a NEW private-chat smartphone selfie/snap of ${(character && character.name) || "the character"}. Use the album item only as visual identity/reference inspiration, never resend or recreate the exact stored photo. ${visible ? `Reference image context: ${visible}.` : ""} ${String(fallbackPrompt || "").trim()}`.trim();
}

async function generateAiChatSnap(
  character,
  snapPrompt,
  addImage,
  media
) {
  const prompt = String(
    snapPrompt || ""
  )
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 500);

  if (!prompt) return null;

  const actorName = String(
    (character && character.name) || "the character"
  ).trim();

  const identityAnchor = await buildCharacterSnapIdentity(
    character,
    media
  );

  const basePrompt = `Create a realistic candid smartphone snap that ${actorName} could naturally send in a private chat. ${prompt}

Character identity anchor:
${identityAnchor || "Use the same person identity consistently across snaps based on the character's established look."}

Rules:
- phone snapshot / snap style
- believable, grounded, social-media-realistic
- no watermark, no text overlay, no collage
- the sender must be recognizably the SAME fictional character/person as in the supplied profile + album reference images
- treat the FIRST reference as the primary face/identity anchor and the remaining album references as secondary identity evidence
- preserve facial structure, eye shape, eyebrows, nose, lips, skin tone, hair identity, age vibe and stable distinguishing features
- create a NEW photograph: do not copy the exact pose, background, composition or outfit from a reference unless the chat request specifically asks for it
- only one version of the character; no collage, no reference-image montage, no duplicate person
- keep the person and scene consistent with the requested character and moment
- if the prompt implies a party, coffee, mirror selfie, street, room, gym or similar, show that naturally.`;

  const referenceImages = characterSnapReferenceImages(
    character,
    media,
    3
  );

  const payload = {
    provider: DEFAULT_IMAGE_PROVIDER,
    model: DEFAULT_IMAGE_MODEL,
    prompt: basePrompt,
    input: basePrompt,
    text: basePrompt,
    size: "1024x1024",
    image_size: "1024x1024",
    quality: "medium",
    output_format: "jpeg",
    response_format: "b64_json",
    background: "auto",
    referenceImages,
    reference_images: referenceImages,
    require_reference: referenceImages.length > 0,
  };

  const result = await requestAiImageProxy(payload);
  if (!result) return null;

  const firstDataRow =
    Array.isArray(result.data) && result.data[0]
      ? result.data[0]
      : null;

  const firstNestedDataRow =
    result && result.result && Array.isArray(result.result.data) && result.result.data[0]
      ? result.result.data[0]
      : (
          result && result.response && Array.isArray(result.response.data) && result.response.data[0]
            ? result.response.data[0]
            : null
        );

  const firstOutputImage =
    result && Array.isArray(result.output) && result.output[0] && Array.isArray(result.output[0].content)
      ? result.output[0].content.find((item) => item && (item.b64_json || item.image_url || item.url))
      : null;

  const b64 = String(
    (firstDataRow && firstDataRow.b64_json) ||
    (firstNestedDataRow && firstNestedDataRow.b64_json) ||
    (firstOutputImage && firstOutputImage.b64_json) ||
    result.b64_json ||
    ""
  ).trim();

  let raw = [
    result.dataUrl,
    result.image,
    result.url,
    result.src,
    firstDataRow && (firstDataRow.url || firstDataRow.image_url),
    firstNestedDataRow && (firstNestedDataRow.url || firstNestedDataRow.image_url),
    firstOutputImage && (firstOutputImage.image_url || firstOutputImage.url),
    b64 ? `data:image/jpeg;base64,${b64}` : "",
  ].find(
    (value) =>
      typeof value === "string" &&
      String(value).trim()
  );

  if (!raw) return null;

  raw = String(raw).trim();

  let imageId = "";
  let image = raw;

  if (
    isInlineImageData(raw) &&
    typeof addImage === "function"
  ) {
    const mime =
      (raw.match(/^data:([^;]+);/i) || [])[1] ||
      "image/jpeg";

    const ref = addImage(raw, {
      category: "chat",
      ownerCharacterId:
        (character && character.id) || "",
      originalFileName: `${
        (character && character.username) ||
        (character && character.id) ||
        "ai"
      }-snap-${uid()}.jpg`,
      mimeType: mime,
    });

    imageId = imageIdOf(ref) || "";
    image = imageId ? "" : raw;
  }

  let imageDescription = String(
    result.vision ||
    result.description ||
    result.caption ||
    result.note ||
    ""
  )
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 700);

  if (!imageDescription && isInlineImageData(raw)) {
    try {
      imageDescription = await analyzeImageDataUrl(
        raw,
        `Describe what is visibly shown in this private snap from ${actorName} in 1-3 concise sentences. Mention only visible people, clothing, activity, setting, objects and mood.`
      );
    } catch (visionErr) {
      console.warn(
        "Generated chat snap analysis failed:",
        visionErr
      );
    }
  }

  return {
    imageId,
    image,
    imageDescription,
  };
}

function worldSyncRev(w) {
  return Math.max(
    0,
    Math.floor(
      Number(
        w && w.syncRev
      ) || 0
    )
  );
}

async function serverWorldPeek(code) {
  const c = encodeURIComponent(
    String(code || "")
      .trim()
      .toLowerCase()
  );

  return apiJson(
    `/world/peek?code=${c}`,
    {
      method: "GET",
    }
  );
}

async function serverSaveWorld(world) {
  return apiJson("/world/save", {
    method: "POST",
    body: JSON.stringify({
      world,
      syncRev:
        worldSyncRev(world),
    }),
  });
}
function migrate(w) {
  if (!w || !w.universe) return w;

  /*
   * syncRev kizárólag a PostgreSQL szerver által kezelt
   * konkurencia-verzió. Régi világok 0-ról indulnak.
   */
  w.syncRev =
    worldSyncRev(w);

  if (!w.universe.year) w.universe.year = String(new Date().getFullYear());
  if (w.universe.date === undefined) w.universe.date = "";
  ensureStorySettings(w);
  const y = worldYear(w);
  const fix = (c) => {
    if (c && !c.birth && c.age && y) {
      const a = Number(String(c.age).replace(/\D/g, ""));
      if (a > 0 && a < 120) c.birth = String(y - a);
    }
  };
  ["rels", "chats", "mems", "accounts", "players", "deleted", "notify", "charMemory", "userSettings", "images"].forEach((k) => { if (!w[k]) w[k] = {}; });
  ["posts", "log", "scenes", "groups", "notes", "inventory", "diary"].forEach((k) => { if (!w[k]) w[k] = []; });



  /*
   * CRASH-GUARD: a posts/comments adatot a migráció LEGELEJÉN tisztítjuk,
   * még mielőtt bármely memória-, social-, follow- vagy feed-helper hozzáérne.
   * Régi/félbemaradt syncből maradó null/undefined post így nem juthat el
   * egyetlen `post.comments` olvasásig sem.
   */
  sanitizeWorldPosts(w);

  if (!w.universe.at) w.universe.at = 0;

  // Régi, egyfelhasználós világ átemelése fiókos szerkezetre.
  if (w.player && typeof w.player === "object") {
    const pid = w.player.id || "player";
    if (!w.players[pid]) w.players[pid] = { ...w.player, id: pid };
    if (!w.accounts[pid]) {
      w.accounts[pid] = {
        id: pid,
        username: normUser(w.player.username || w.player.name || "jatekos") || "jatekos",
        salt: "", hash: "",
        created: now(),
      };
    }
    Object.keys(w.chats).forEach((k) => {
      if (k.indexOf("|") === -1) { w.chats[chatKey(pid, k)] = w.chats[k]; delete w.chats[k]; }
    });
    delete w.player;
  }
  // Az összevont vagy törölt profilok nem éledhetnek újra.
  Object.keys(w.deleted || {}).forEach((id) => { delete w.players[id]; delete w.accounts[id]; });

  Object.keys(w.players).forEach((id) => fix(w.players[id]));
  (w.chars || []).forEach(fix);

  /*
   * vConnections migráció: a régi Side character / Mellékszereplő entitásokat
   * egyszeri szöveges karakterkánonná alakítjuk, majd megszüntetjük őket mint világ-entitásokat.
   * Így régi mentés sem veszti el az anya/apa/ex/mentor infókat, de ezek többé nem kapnak ID-t,
   * profilt, relationship score-t, chatet vagy AI-agent szerepet.
   */
  const legacyExtras = Array.isArray(w.extras) ? w.extras.filter(Boolean) : [];
  if (legacyExtras.length) {
    const legacyIds = new Set(legacyExtras.map((x) => String(x.id || "")).filter(Boolean));
    const active = humanChars(w).concat(w.chars || []).filter(Boolean);
    const appendConnection = (character, line) => {
      if (!character || !line) return;
      const before = String(character.connections || "").trim();
      if (before.toLowerCase().includes(line.toLowerCase())) return;
      character.connections = [before, line].filter(Boolean).join("\n").slice(0, 4000);
    };
    active.forEach((character) => {
      legacyExtras.forEach((person) => {
        if (!person || !person.id) return;
        const direct = w.rels[relKey(character.id, person.id)] || w.rels[`${character.id}|${person.id}`] || null;
        const reverseShared = w.rels[`${person.id}|${character.id}`] || null;
        const rel = direct || reverseShared;
        if (!rel) return;
        const pieces = [String(person.name || "").trim() || "Unnamed person"];
        if (person.note) pieces.push(String(person.note).trim());
        const bond = String(rel.bond || rel.type || "").trim();
        if (bond) pieces.push(`Relationship: ${bond}`);
        if (rel.hidden) pieces.push(`Private feeling: ${String(rel.hidden).trim()}`);
        appendConnection(character, pieces.filter(Boolean).join(" — "));
      });
    });
    Object.keys(w.rels || {}).forEach((key) => {
      const ids = key.includes(">") ? key.split(">") : key.split("|");
      if (ids.some((id) => legacyIds.has(String(id)))) delete w.rels[key];
    });
  }
  delete w.extras;

  Object.keys(w.players || {}).forEach((id) => {
    if (!w.userSettings[id]) w.userSettings[id] = { language: asLang(w.aiLang || "hu"), contentLevel: "mature" };
    else {
      w.userSettings[id].language = asLang(w.userSettings[id].language);
      w.userSettings[id].contentLevel = "mature";
    }
  });

  // régi memóriák felhúzása az új, karakterenkénti tudás-tárba
  Object.keys(w.mems || {}).forEach((id) => {
    const mem = ensureCharMemory(w, id);
    const items = (w.mems[id] || []).map((text) => ({ text, source: "legacy_memory", confidence: 0.85, timestamp: now() }));
    mem.knownFacts = mergeKnowledgeItems(mem.knownFacts, items, "fact", 32);
  });

  /* Régi roleplay jeleneteket is felhúzzuk az új Event-sémára. */
  {
    const fallbackPlayerId =
      (w.owner && w.players && w.players[w.owner] ? w.owner : "") ||
      Object.keys(w.players || {})[0] ||
      "";

    (w.scenes || []).forEach((scene) => {
      ensureSceneEventState(scene);
      if (!fallbackPlayerId) return;

      /*
       * v43 could overwrite the optimistic player's authorId with n.meId even
       * though the persisted world object itself does not store meId. Repair
       * those already-saved journal entries and their matching turn copies.
       */
      scene.playerTurnJournal = (scene.playerTurnJournal || []).map((turn) =>
        turn && !turn.authorId
          ? { ...turn, authorId: fallbackPlayerId }
          : turn
      );

      const journalIds = new Set(
        (scene.playerTurnJournal || [])
          .filter(Boolean)
          .map((turn) => String(turn.id || ""))
      );

      scene.turns = (scene.turns || []).map((turn) =>
        turn && !turn.authorId && journalIds.has(String(turn.id || ""))
          ? { ...turn, authorId: fallbackPlayerId }
          : turn
      );

      scene.turns = mergeRoleplayTurnStreams(
        scene.turns,
        scene.playerTurnJournal
      );
    });
  }

  /* AI Roleplay-meghívások lejárata: a régi, válasz nélkül maradt pending meghívás
     ne maradjon örökké aktív. A scene rekord + emlékezet megmarad, az aktív UI-ból archiváljuk. */
  expirePendingRoleplayInvites(w, now());

  /* Idempotens második védőháló régi migrációs ágak után. */
  sanitizeWorldPosts(w);
  // a lejárt jegyzetek nem cipelődnek tovább; szerzőnként egy marad
  {
    const byAuthor = {};
    (w.notes || []).forEach((x) => {
      if (!x || !x.authorId || now() - (x.ts || 0) >= NOTE_LIFE) return;
      const cur = byAuthor[x.authorId];
      if (!cur || (x.ts || 0) > (cur.ts || 0)) byAuthor[x.authorId] = x;
    });
    w.notes = Object.keys(byAuthor).map((k) => byAuthor[k]).sort((a, b) => (b.ts || 0) - (a.ts || 0));
  }
  // A régi, kétirányban közös kapcsolatokat szétbontjuk: mindkét fél
  // ugyanazt az értéket kapja kiindulásnak, onnantól külön alakulnak.
  {
    const split = {};
    Object.keys(w.rels || {}).forEach((k) => {
      const r = w.rels[k];
      if (!r) return;
      if (k.indexOf(">") >= 0) { split[k] = r; return; }
      const parts = k.split("|");
      if (parts.length !== 2) return;
      const [x, y] = parts;
      const pair = BOND_PAIR[r.bond || r.type || ""] || r.bond || r.type || "";
      if (!split[relKey(x, y)]) split[relKey(x, y)] = { ...r };
      if (!split[relKey(y, x)]) split[relKey(y, x)] = { ...r, bond: pair };
    });
    w.rels = split;
  }

  Object.keys(w.rels).forEach((k) => {
    const r = w.rels[k];
    if (!r) return;
    if (r.bond === undefined) r.bond = "";
    if (r.fixed === undefined) r.fixed = false;
    if (r.mood === undefined) r.mood = "";
    if (r.why === undefined) r.why = "";
    if (!r.bond && r.type) { r.bond = r.type; r.fixed = FIXED_BONDS.indexOf(r.type) >= 0; r.type = ""; }
  });

  // képhivatkozások migrációja: a tényleges fájl marad külön tárolva, itt csak a stabil metaél marad.
  const noteImage = (ref, patch) => {
    const id = imageIdOf(ref);
    if (id) registerImageMeta(w, id, patch);
  };
  Object.keys(w.players || {}).forEach((id) => noteImage(w.players[id] && w.players[id].avatar, { category: "profile", ownerUserId: id }));
  (w.chars || []).forEach((c) => {
    noteImage(c && c.avatar, { category: "profile", ownerCharacterId: c && c.id });
    (albumOf(c) || []).forEach((item) => {
      const ref = item && (item.imageId ? imageRef(item.imageId) : item.src);
      const iid = imageIdOf(ref);
      if (iid && item && !item.imageId) item.imageId = iid;
      noteImage(ref, { category: "album", ownerCharacterId: c && c.id });
    });
  });
  (w.posts || []).forEach((p) => {
    if (p && !p.imageId) p.imageId = imageIdOf(p.image);
    noteImage(p && (p.imageId ? imageRef(p.imageId) : p.image), { category: "post", ownerCharacterId: p && p.authorId });
  });
  return w;
}

async function loadWorld(code) {
  const primary = await loadPrimaryWorld(code);
  const cloudSnap = await loadLatestValidWorldSnapshot(code, true);
  const localSnap = await loadLatestValidWorldSnapshot(code, false);

  return newestWorldCandidate([
    primary,
    cloudSnap,
    localSnap
  ]);
}

function validWorldState(w) {
  return !!(w && typeof w === "object" && w.universe && typeof w.universe === "object" && w.accounts && w.players && Array.isArray(w.chars));
}

function newerWorldCandidate(a, b) {
  if (!a) return b || null;
  if (!b) return a || null;
  const ar = Number(a.rev || 0), br = Number(b.rev || 0);
  if (ar !== br) return ar > br ? a : b;
  const at = Number((a.universe && a.universe.at) || a.updatedAt || 0);
  const bt = Number((b.universe && b.universe.at) || b.updatedAt || 0);
  return at >= bt ? a : b;
}

function newestWorldCandidate(list) {
  return (list || []).filter(validWorldState).reduce((best, item) => newerWorldCandidate(best, item), null);
}

async function readBigScoped(base, shared) {
  const head = await store.get(base + ":n", shared);
  if (head) {
    const n = Number(head.value) || 0;
    let txt = "";
    for (let i = 0; i < n; i++) {
      const part = await store.get(base + ":" + i, shared);
      if (!part) return null;
      txt += part.value;
    }
    return txt;
  }
  const r = await store.get(base, shared);
  return r ? r.value : null;
}

async function writeBigScoped(base, txt, shared) {
  const parts = [];
  for (let i = 0; i < txt.length; i += MCHUNK) parts.push(txt.slice(i, i + MCHUNK));
  if (!parts.length) parts.push("");

  const head = await store.get(base + ":n", shared);
  const old = head ? Number(head.value) || 0 : 0;

  for (let i = 0; i < parts.length; i++) {
    if (!(await store.set(base + ":" + i, parts[i], shared))) return false;
  }
  if (!(await store.set(base + ":n", String(parts.length), shared))) return false;

  for (let i = parts.length; i < old; i++) await store.del(base + ":" + i, shared);
  if (!old) await store.del(base, shared);
  return true;
}

async function dropBigScoped(base, shared) {
  const head = await store.get(base + ":n", shared);
  const n = head ? Number(head.value) || 0 : 0;
  for (let i = 0; i < n; i++) await store.del(base + ":" + i, shared);
  await store.del(base + ":n", shared);
  await store.del(base, shared);
}

const SAVE_HISTORY_LIMIT = 8;
const SNAP_META_KEY = (code, shared) => `${KEY(code)}:${shared ? "cloud" : "local"}:save-index`;
const SNAP_DATA_KEY = (code, shared, id) => `${KEY(code)}:${shared ? "cloud" : "local"}:save:${id}`;

async function loadSaveIndex(code, shared) {
  const r = await store.get(SNAP_META_KEY(code, shared), shared);
  if (!r) return [];
  try {
    const list = JSON.parse(r.value);
    return Array.isArray(list) ? list : [];
  } catch (e) { return []; }
}

async function writeSaveIndex(code, shared, list) {
  return store.set(SNAP_META_KEY(code, shared), JSON.stringify(list || []), shared);
}

async function writeWorldSnapshot(code, world, shared) {
  if (!validWorldState(world)) return false;
  const id = `${now()}-${uid()}`;
  const entry = {
    id,
    code,
    rev: Number(world.rev || 0),
    syncRev: worldSyncRev(world),
    savedAt: now(),
    updatedAt: Number((world.universe && world.universe.at) || 0),
  };
  const payload = JSON.stringify({ ...entry, gameState: world });
  if (!(await writeBigScoped(SNAP_DATA_KEY(code, shared, id), payload, shared))) return false;
  const existing = await loadSaveIndex(code, shared);
  const next = [entry].concat(existing.filter((x) => x && x.id !== id)).sort((a, b) => {
    if ((b.rev || 0) !== (a.rev || 0)) return (b.rev || 0) - (a.rev || 0);
    return (b.savedAt || 0) - (a.savedAt || 0);
  });
  const keep = next.slice(0, SAVE_HISTORY_LIMIT);
  const stale = next.slice(SAVE_HISTORY_LIMIT);
  await writeSaveIndex(code, shared, keep);
  for (let i = 0; i < stale.length; i++) await dropBigScoped(SNAP_DATA_KEY(code, shared, stale[i].id), shared);
  return true;
}

async function loadLatestValidWorldSnapshot(code, shared) {
  const list = await loadSaveIndex(code, shared);
  for (let i = 0; i < list.length; i++) {
    const meta = list[i];
    const txt = await readBigScoped(SNAP_DATA_KEY(code, shared, meta.id), shared);
    if (!txt) continue;
    try {
      const parsed = JSON.parse(txt);
      const migrated = migrate(parsed && parsed.gameState);
      if (validWorldState(migrated)) return migrated;
    } catch (e) { /* sérült snapshot, ugrunk a következőre */ }
  }
  return null;
}

async function loadPrimaryWorld(code) {
  const txt = await readBig(KEY(code));
  if (!txt) return null;
  try {
    const parsed = JSON.parse(txt);
    const migrated = migrate(parsed);
    return validWorldState(migrated) ? migrated : null;
  } catch (e) { return null; }
}

/* Elemenkénti "utolsó írás nyer" összefésülés. */
const stamp = (o) => (o && (o.updatedAt || o.at || 0)) || 0;
const newer = (a, b) => (stamp(a) >= stamp(b) ? a : b);

function contentOf(w) {
  if (!w) return "";
  const copy = { ...w };

  /*
   * A rev helyi tartalom-verzió, a syncRev pedig
   * szerver-konkurencia verzió. Egyik se számít
   * önmagában tartalmi változásnak.
   */
  delete copy.rev;
  delete copy.syncRev;

  /*
   * A backend minden sikeres mentésnél technikailag frissíti universe.at-et.
   * Ez nem játékbeli tartalom, ezért nem okozhat hamis device-conflictet.
   */
  if (copy.universe && typeof copy.universe === "object") {
    copy.universe = { ...copy.universe };
    delete copy.universe.at;
  }

  return JSON.stringify(copy);
}

function mergeById(remoteArr, localArr, deleted) {
  const byId = {}, order = [];
  (remoteArr || []).forEach((it) => { if (it && it.id) { byId[it.id] = it; order.push(it.id); } });
  (localArr || []).forEach((it) => {
    if (!it || !it.id) return;
    if (!byId[it.id]) { byId[it.id] = it; order.push(it.id); }
    else byId[it.id] = newer(it, byId[it.id]);
  });
  return order.filter((id) => !(deleted && deleted[id])).map((id) => byId[id]);
}

function mergeMapById(remoteMap, localMap) {
  const out = { ...(remoteMap || {}) };
  Object.keys(localMap || {}).forEach((k) => {
    out[k] = out[k] ? newer(localMap[k], out[k]) : localMap[k];
  });
  return out;
}

function normalizeMemoryText(text) {
  const clean = String(text || "")
    .replace(/\s+/g, " ")
    .replace(/^[\s"“”'`]+|[\s"“”'`]+$/g, "")
    .trim();
  if (!clean) return "";
  return clean.length > 200 ? `${clean.slice(0, 197)}…` : clean;
}

function mergeMemoryEntries(existing = [], incoming = [], limit = 16) {
  const out = [];
  const seen = new Set();
  [...(existing || []), ...(incoming || [])].forEach((entry) => {
    const normalized = normalizeMemoryText(entry);
    if (!normalized) return;
    const key = normalized.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    out.push(normalized);
  });
  return out.slice(-limit);
}

function mergeWorlds(remote, local) {
  if (!remote) {
    const only = { ...local };
    delete only.extras;
    return only;
  }
  const out = { ...local };
  delete out.extras;
  out.rev = Math.max(remote.rev || 0, local.rev || 0) + 1;

  out.deleted = { ...(remote.deleted || {}), ...(local.deleted || {}) };
  out.accounts = { ...(remote.accounts || {}), ...(local.accounts || {}) };
  out.players = mergeMapById(remote.players, local.players);
  out.userSettings = { ...(remote.userSettings || {}), ...(local.userSettings || {}) };
  out.images = { ...(remote.images || {}), ...(local.images || {}) };

  // Az összevont vagy törölt profilok nem jöhetnek vissza a másik gépről.
  Object.keys(out.deleted).forEach((id) => { delete out.players[id]; delete out.accounts[id]; });
  Object.keys(out.deleted).forEach((id) => { delete out.userSettings[id]; });

  out.chars = mergeById(remote.chars, local.chars, out.deleted);
  out.universe = newer(local.universe, remote.universe);
  out.rels = mergeMapById(remote.rels, local.rels);

  const byId = {}, order = [];
  (local.posts || []).concat(remote.posts || []).forEach((po) => {
    if (!po || !po.id) return;

    const safeComments = Array.isArray(po.comments)
      ? po.comments.filter((c) => c && typeof c === "object")
      : [];

    if (!byId[po.id]) {
      byId[po.id] = { ...po, comments: safeComments.slice() };
      order.push(po.id);
      return;
    }

    const t = byId[po.id];
    if (!Array.isArray(t.comments)) t.comments = [];
    t.likes = Math.max(t.likes || 0, po.likes || 0);
    safeComments.forEach((c) => {
      if (c.id && !t.comments.some((x) => x && x.id === c.id)) t.comments.push(c);
    });
  });
  order.forEach((id) => {
    const row = byId[id];
    if (!row) return;
    row.comments = safePostComments(row);
    row.comments.sort((a, b) => (a.ts || 0) - (b.ts || 0));
  });
  out.posts = order.filter((id) => !out.deleted[id]).map((id) => byId[id]).sort((a, b) => (b.ts || 0) - (a.ts || 0));

  const sById = {}, sOrder = [];
  const mergeSceneTurns = (a, b) => {
    const rows = [];
    const seen = new Set();
    [...(a || []), ...(b || [])]
      .filter(Boolean)
      .sort((x, y) => (Number(x.ts) || 0) - (Number(y.ts) || 0))
      .forEach((turn) => {
        const key = turn.id || `${turn.authorId || "?"}|${Number(turn.ts) || 0}|${turn.kind || ""}|${String(turn.text || "").trim()}`;
        if (seen.has(key)) return;
        seen.add(key);
        rows.push(turn);
      });
    return rows;
  };
  (local.scenes || []).concat(remote.scenes || []).forEach((sc) => {
    if (!sc || !sc.id) return;
    if (!sById[sc.id]) {
      sById[sc.id] = {
        ...sc,
        playerTurnJournal: mergeRoleplayTurnStreams(sc.playerTurnJournal || []),
        turns: mergeRoleplayTurnStreams(sc.turns || [], sc.playerTurnJournal || []),
      };
      sOrder.push(sc.id);
      return;
    }
    const current = sById[sc.id];
    const meta = newer(sc, current);
    const mergedPlayerJournal = mergeRoleplayTurnStreams(
      current.playerTurnJournal || [],
      sc.playerTurnJournal || []
    );
    sById[sc.id] = {
      ...current,
      ...meta,
      playerTurnJournal: mergedPlayerJournal,
      turns: mergeRoleplayTurnStreams(
        current.turns,
        sc.turns,
        mergedPlayerJournal
      ),
      sceneMemory: stamp(sc) >= stamp(current)
        ? (sc.sceneMemory || current.sceneMemory)
        : (current.sceneMemory || sc.sceneMemory),
    };
  });
  out.scenes = sOrder.filter((id) => !out.deleted[id]).map((id) => sById[id]);
  out.scenes.forEach((scene) => ensureSceneEventState(scene));

  /* Event reward inventory + diary are id-based append-only world data. */
  out.inventory = mergeById(remote.inventory || [], local.inventory || [], null)
    .sort((a, b) => (b.ts || 0) - (a.ts || 0))
    .slice(0, 500);
  out.diary = mergeById(remote.diary || [], local.diary || [], null)
    .sort((a, b) => (b.ts || 0) - (a.ts || 0))
    .slice(0, 300);

  const gById = {}, gOrder = [];
  (local.groups || []).concat(remote.groups || []).forEach((g) => {
    if (!g || !g.id) return;
    if (!gById[g.id]) { gById[g.id] = { ...g, msgs: (g.msgs || []).slice() }; gOrder.push(g.id); return; }
    const t = gById[g.id];
    const meta = newer(g, t);
    t.name = meta.name; t.members = meta.members; t.updatedAt = stamp(meta);
    (g.msgs || []).forEach((m) => { if (m && m.id && !t.msgs.some((x) => x.id === m.id)) t.msgs.push(m); });
  });
  gOrder.forEach((id) => gById[id].msgs.sort((a, b) => (a.ts || 0) - (b.ts || 0)));
  out.groups = gOrder.filter((id) => !out.deleted[id]).map((id) => gById[id]);

  // jegyzetek: szerzőnként a frissebb marad, a lejártak kiesnek
  {
    const byAuthor = {};
    (local.notes || []).concat(remote.notes || []).forEach((x) => {
      if (!x || !x.authorId || now() - (x.ts || 0) >= NOTE_LIFE) return;
      const cur = byAuthor[x.authorId];
      if (!cur || (x.ts || 0) > (cur.ts || 0)) byAuthor[x.authorId] = x;
    });
    out.notes = Object.keys(byAuthor).map((k) => byAuthor[k]).sort((a, b) => (b.ts || 0) - (a.ts || 0));
  }

  out.chats = { ...(remote.chats || {}) };
  Object.keys(local.chats || {}).forEach((k) => {
    const a = local.chats[k] || [], b = (remote.chats || {})[k] || [];
    out.chats[k] = a.length >= b.length ? a : b;
  });
  // az összevont profil régi beszélgetései ne jöjjenek vissza
  Object.keys(out.chats).forEach((k) => { if (out.deleted[k.split("|")[0]]) delete out.chats[k]; });

  // értesítések: fiókonként unió, a frissebb elöl
  out.notify = { ...(remote.notify || {}) };
  Object.keys(local.notify || {}).forEach((k) => {
    const seen = {}, list = [];
    (local.notify[k] || []).concat(out.notify[k] || []).forEach((x) => {
      if (!x || !x.id || seen[x.id]) return;
      seen[x.id] = 1; list.push(x);
    });
    out.notify[k] = list.sort((x, y) => (y.ts || 0) - (x.ts || 0)).slice(0, 60);
  });

  out.mems = { ...(remote.mems || {}) };
  Object.keys(local.mems || {}).forEach((k) => {
    out.mems[k] = mergeMemoryEntries(out.mems[k], local.mems[k], 16);
  });
  Object.keys(out.deleted).forEach((id) => { delete out.mems[id]; });

  out.charMemory = { ...(remote.charMemory || {}) };
  Object.keys(local.charMemory || {}).forEach((k) => {
    const base = out.charMemory[k] || defaultCharacterMemory();
    const mine = local.charMemory[k] || defaultCharacterMemory();
    const shared = { ...(base.roleplayShared || {}) };
    Object.keys(mine.roleplayShared || {}).forEach((targetId) => {
      shared[targetId] = mergeKnowledgeItems(
        shared[targetId],
        mine.roleplayShared[targetId],
        "roleplay_shared",
        36
      );
    });
    const newerState = Number(mine?.selfState?.updatedAt || 0) >= Number(base?.selfState?.updatedAt || 0)
      ? (mine.selfState || {})
      : (base.selfState || {});
    const baseRuntime = base.agentRuntime || {};
    const mineRuntime = mine.agentRuntime || {};
    const newerRuntime = Number(mineRuntime.updatedAt || 0) >= Number(baseRuntime.updatedAt || 0)
      ? mineRuntime
      : baseRuntime;
    const mergeRuntimeRows = (a, b, limit) => {
      const rows = [];
      const seen = new Set();
      [...(a || []), ...(b || [])]
        .filter(Boolean)
        .sort((x, y) => (Number(x && x.ts) || 0) - (Number(y && y.ts) || 0))
        .forEach((row) => {
          const key = String(row && (row.id || `${row.surface || ""}|${row.refId || ""}|${row.text || ""}`));
          if (!key || seen.has(key)) return;
          seen.add(key);
          rows.push(row);
        });
      return rows.slice(-limit);
    };
    out.charMemory[k] = {
      knownCharacters: { ...(base.knownCharacters || {}), ...(mine.knownCharacters || {}) },
      knownFacts: mergeKnowledgeItems(base.knownFacts, mine.knownFacts, "fact", 80),
      witnessedEvents: mergeKnowledgeItems(base.witnessedEvents, mine.witnessedEvents, "event", 80),
      conversations: mergeKnowledgeItems(base.conversations, mine.conversations, "conversation", 100),
      relationshipHistory: { ...(base.relationshipHistory || {}), ...(mine.relationshipHistory || {}) },
      suspicions: mergeKnowledgeItems(base.suspicions, mine.suspicions, "assumption", 50),
      rumors: mergeKnowledgeItems(base.rumors, mine.rumors, "rumor", 60),
      learnedSecrets: mergeKnowledgeItems(base.learnedSecrets, mine.learnedSecrets, "secret", 60),
      emotionalAnchors: mergeKnowledgeItems(base.emotionalAnchors, mine.emotionalAnchors, "anchor", 60),
      personalMilestones: mergeKnowledgeItems(base.personalMilestones, mine.personalMilestones, "milestone", 60),
      roleplayRecent: mergeKnowledgeItems(base.roleplayRecent, mine.roleplayRecent, "roleplay_recent", 40),
      roleplayLongTerm: mergeKnowledgeItems(base.roleplayLongTerm, mine.roleplayLongTerm, "roleplay_long", 70),
      roleplayShared: shared,
      selfState: {
        mood: String(newerState.mood || ""),
        intent: String(newerState.intent || ""),
        openLoops: Array.isArray(newerState.openLoops) ? newerState.openLoops.slice(-8) : [],
        updatedAt: Number(newerState.updatedAt || 0),
      },
      agentRuntime: {
        currentSurface: String(newerRuntime.currentSurface || ""),
        currentTargetId: String(newerRuntime.currentTargetId || ""),
        lastPerceptionAt: Math.max(Number(baseRuntime.lastPerceptionAt || 0), Number(mineRuntime.lastPerceptionAt || 0)),
        lastActionAt: Math.max(Number(baseRuntime.lastActionAt || 0), Number(mineRuntime.lastActionAt || 0)),
        lastAction: String(newerRuntime.lastAction || ""),
        lastActionRef: String(newerRuntime.lastActionRef || ""),
        activeThreads: mergeRuntimeRows(baseRuntime.activeThreads, mineRuntime.activeThreads, 12),
        activePlans: mergeRuntimeRows(baseRuntime.activePlans, mineRuntime.activePlans, 8),
        updatedAt: Math.max(Number(baseRuntime.updatedAt || 0), Number(mineRuntime.updatedAt || 0)),
      },
    };
  });
  Object.keys(out.deleted).forEach((id) => { delete out.charMemory[id]; });

  /* Social ledger + gossip protocol are append-only/id-based and must survive
     conflict reconciliation just like chats and RP turns. */
  out.socialEvents = mergeById(remote.socialEvents || [], local.socialEvents || [], null)
    .sort((a,b) => (Number(b && b.ts) || 0) - (Number(a && a.ts) || 0)).slice(0, 600);
  out.rumors = mergeById(remote.rumors || [], local.rumors || [], null)
    .sort((a,b) => (Number(b && b.ts) || 0) - (Number(a && a.ts) || 0)).slice(0, 160);

  const remoteGp = ensureGossipPropagationState(remote) || { rumors: [], exchanges: [], echoes: [] };
  const localGp = ensureGossipPropagationState(local) || { rumors: [], exchanges: [], echoes: [] };
  const gpById = {};
  [...(remoteGp.rumors || []), ...(localGp.rumors || [])].forEach((r) => {
    if (!r || !r.id) return;
    const cur = gpById[r.id];
    if (!cur) { gpById[r.id] = JSON.parse(JSON.stringify(r)); return; }
    const holders = { ...(cur.holders || {}), ...(r.holders || {}) };
    const echoedBy = { ...(cur.echoedBy || {}), ...(r.echoedBy || {}) };
    gpById[r.id] = { ...(Number(r.updatedAt || 0) >= Number(cur.updatedAt || 0) ? cur : r), ...(Number(r.updatedAt || 0) >= Number(cur.updatedAt || 0) ? r : cur), holders, echoedBy,
      communitiesReached: [...new Set([...(cur.communitiesReached || []), ...(r.communitiesReached || [])])],
      spreadCount: Math.max(Number(cur.spreadCount || 0), Number(r.spreadCount || 0), Object.keys(holders).length - 1),
      publicEchoCount: Math.max(Number(cur.publicEchoCount || 0), Number(r.publicEchoCount || 0), Object.keys(echoedBy).length),
      updatedAt: Math.max(Number(cur.updatedAt || 0), Number(r.updatedAt || 0)),
      lastSpreadAt: Math.max(Number(cur.lastSpreadAt || 0), Number(r.lastSpreadAt || 0)),
      lastEchoAt: Math.max(Number(cur.lastEchoAt || 0), Number(r.lastEchoAt || 0)) };
  });
  const exById = {};
  [...(remoteGp.exchanges || []), ...(localGp.exchanges || [])].forEach((x) => { if (x && x.id) exById[x.id] = x; });
  const echoById = {};
  [...(remoteGp.echoes || []), ...(localGp.echoes || [])].forEach((x) => { if (x && x.id) echoById[x.id] = x; });
  out.gossipPropagation = {
    version: 2,
    rumors: Object.values(gpById).sort((a,b) => Number(a.createdAt || 0) - Number(b.createdAt || 0)).slice(-220),
    exchanges: Object.values(exById).sort((a,b) => Number(a.ts || 0) - Number(b.ts || 0)).slice(-500),
    echoes: Object.values(echoById).sort((a,b) => Number(a.ts || 0) - Number(b.ts || 0)).slice(-320),
    lastRoundAt: Math.max(Number(remoteGp.lastRoundAt || 0), Number(localGp.lastRoundAt || 0)),
    lastEchoAt: Math.max(Number(remoteGp.lastEchoAt || 0), Number(localGp.lastEchoAt || 0)),
  };

  const seenLog = {};
  out.log = (local.log || []).concat(remote.log || [])
    .filter((l) => (seenLog[l] ? false : (seenLog[l] = 1))).slice(0, 30);

  return out;
}

async function saveWorld(w) {
  if (!w || !w.code) return false;

  /*
   * LOCAL EMERGENCY BACKUP ONLY.
   * Online játék közben ez soha nem az igazság forrása.
   */
  return writeBigScoped(
    KEY(w.code),
    JSON.stringify(w),
    false
  );
}

/*
 * A név kompatibilitás miatt marad, de NEM merge-el
 * semmilyen régi böngészős világot az online állapotba.
 * PostgreSQL az egyetlen authoritative world online.
 */
async function saveWorldMerged(local) {
  if (!local || !local.code) {
    return {
      world: local,
      mode: "memory",
    };
  }

  const snapshot =
    JSON.parse(
      JSON.stringify(local)
    );

  let snapshotOk = false;
  let primaryOk = false;

  try {
    snapshotOk =
      await writeWorldSnapshot(
        local.code,
        snapshot,
        false
      );
  } catch (e) {
    snapshotOk = false;
  }

  try {
    primaryOk =
      await saveWorld(snapshot);
  } catch (e) {
    primaryOk = false;
  }

  return {
    world: snapshot,
    mode:
      snapshotOk || primaryOk
        ? "local"
        : "memory",
  };
}

/* Közös szobajegyzék: minden létrehozott szoba bekerül ide, oda, ahol maguk a
   világok is laknak. Így a szobák akkor is megtalálhatók, ha az eszközön tárolt
   saját listád üres vagy elavult. */
const INDEX = "masvilag:index";

async function loadIndex() {
  const r = await store.get(INDEX, true);
  let list = [];

  if (r) {
    try {
      const a = JSON.parse(r.value);
      list = Array.isArray(a) ? a : [];
    } catch (e) {
      list = [];
    }
  }

  /*
    Egyszeri régi Beacon Falls takarítás.
    A korábbi recovery verzió ezt beégette a közös indexbe.
  */
  const cleaned = list.filter(
    (x) => x && x.code !== "beaconfalls"
  );

  if (cleaned.length !== list.length) {
    await store.set(
      INDEX,
      JSON.stringify(cleaned),
      true
    );
  }

  return cleaned;
}
async function addToIndex(w, meId) {
  if (!w || !w.code) return false;
  const list = await loadIndex();
  const prev = list.find((x) => x && x.code === w.code) || {};
  const rest = list.filter((x) => x && x.code !== w.code);
  const acc = meId && w.accounts ? w.accounts[meId] : null;
  const entry = {
    code: w.code,
    name: (w.universe && w.universe.name) || w.code,
    // a felhasználónév a jegyzékben is megvan, így másik eszközön elég a jelszó
    user: (acc && acc.username) || prev.user || "",
    ts: now(),
  };
  return store.set(INDEX, JSON.stringify([entry].concat(rest).slice(0, 60)), true);
}
async function removeFromIndex(code) {
  const list = await loadIndex();
  return store.set(INDEX, JSON.stringify(list.filter((x) => x && x.code !== code)), true);
}

