function sysTextFor(w, playerId, key, params) {
  const lang = worldLanguage(w, playerId);
  const dict = SYS_TEXT[lang] || SYS_TEXT.hu;
  const tpl = dict[key] || SYS_TEXT.hu[key] || key;
  return fillTpl(tpl, params || {});
}

function sysLangText(w, playerId, hu, en) {
  return worldLanguage(w, playerId) === "en" ? en : hu;
}

const BUILD_VERSION = "v57-rp-invites-gossip-reactions";

const AUTO = "masvilag:auto";
/*
 * LIVE WORLD FIXED MODE
 *
 * Mindig be van kapcsolva, gyors "live" ütemet használ.
 * Régi eszközön mentett "off" / ritkább érték sem írhatja ezt felül.
 */
const AUTO_DEFAULT = {
  on: true,

  /*
   * Valóban élő háttérvilág:
   * 0.25 perc = kb. 15 mp két AUTONÓM tartalmi kör között.
   *
   * Az AI queue saját token/rate-limit throttlingja ettől külön működik,
   * tehát ha a providernek több pihenő kell, továbbra is biztonságosan vár.
   */
  every: Math.max(0.12, LIVE_WORLD_CONTENT_INTERVAL_MS / 60000),
};

async function loadAuto() {
  return {
    ...AUTO_DEFAULT,
  };
}

async function saveAuto() {
  if (!hasStore) {
    mem[AUTO] = {
      ...AUTO_DEFAULT,
    };

    return true;
  }

  try {
    await window.storage.set(
      AUTO,
      JSON.stringify(
        AUTO_DEFAULT
      ),
      false
    );

    return true;
  } catch (e) {
    return false;
  }
}

/* A saját világaid listája ezen az eszközön. */
const ROOMS = "masvilag:rooms";
async function loadRooms() {
  if (!hasStore) return mem[ROOMS] || [];
  try {
    const r = await window.storage.get(ROOMS, false);
    const list = r ? JSON.parse(r.value) : [];
    return Array.isArray(list) ? list : [];
  } catch (e) { return []; }
}
async function saveRooms(list) {
  if (!hasStore) { mem[ROOMS] = list; return true; }
  try { await window.storage.set(ROOMS, JSON.stringify(list), false); return true; }
  catch (e) { return false; }
}
async function rememberRoom(entry) {
  const list = await loadRooms();
  const rest = list.filter((r) => r && r.code !== entry.code);
  return saveRooms([{ ...entry, ts: now() }].concat(rest).slice(0, 40));
}
async function forgetRoom(code) {
  const list = await loadRooms();
  return saveRooms(list.filter((r) => r && r.code !== code));
}
async function destroyWorld(code) {
  await dropBig(KEY(code));
  await dropMedia(code);
  await removeFromIndex(code);
  return true;
}

/* Minden másvilág-adat törlése ebből a tárolóból: világok, képtárak,
   a saját szobalistád és a bejelentkezésed. Nincs visszaút. */
async function wipeEverything() {
  let count = 0;
  if (!hasStore) { Object.keys(mem).forEach((k) => delete mem[k]); return count; }
  const sweep = async (shared) => {
    let cursor = null;
    for (let round = 0; round < 20; round++) {
      let res = null;
      try { res = await window.storage.list("masvilag:", shared); } catch (e) { return; }
      const raw = (res && res.keys) || [];
      const keys = raw.map((k) => (typeof k === "string" ? k : (k && k.key))).filter(Boolean);
      if (!keys.length) return;
      for (let i = 0; i < keys.length; i++) {
        try { await window.storage.delete(keys[i], shared); count++; } catch (e) { /* lehet, hogy már nincs */ }
      }
      if (keys.length < 2) return;
      if (cursor === keys[keys.length - 1]) return;
      cursor = keys[keys.length - 1];
    }
  };
  await sweep(true);
  await sweep(false);
  return count;
}

/* Egy tárolókulcs mérete korlátos, ezért a nagy tartalmakat — a világot és a
   képtárat — darabokban mentjük. Így hosszú játék és sok kép után sem akad el
   a mentés, és nem kapsz hibaüzenetet. */
const MCHUNK = 2500000;

async function readBig(base) {
  return readBigScoped(base, true);
}

async function writeBig(base, txt) {
  return writeBigScoped(base, txt, true);
}

async function dropBig(base) {
  return dropBigScoped(base, true);
}
const mediaBytes = (m) =>
  Object.keys(
    m || {}
  ).reduce(
    (sum, k) => {
      const raw =
        m[k];

      if (!raw) {
        return sum;
      }

      if (
        typeof raw ===
        "string"
      ) {
        return (
          sum +
          raw.length
        );
      }

      return (
        sum +
        String(
          raw.dataUrl ||
          raw.url ||
          ""
        ).length
      );
    },
    0
  );

/*
 * A backend 45 MB körüli teljes JSON payloadot enged.
 * 32 MB base64 képanyag mellett marad tartalék a metaadatoknak
 * és kisebb a mobil böngésző memória-csúcsa.
 */
const MEDIA_CAP =
  32 * 1048576;

function mediaFingerprint(
  media
) {
  return Object.keys(
    media || {}
  )
    .sort()
    .map((id) => {
      const raw =
        media[id];

      if (!raw) {
        return `${id}:0`;
      }

      if (
        typeof raw ===
        "string"
      ) {
        return `${id}:legacy:${raw.length}:${raw.slice(-18)}`;
      }

      const data =
        String(
          raw.dataUrl ||
          raw.url ||
          ""
        );

      return [
        id,
        raw.status || "",
        raw.updatedAt || "",
        raw.deletedAt || "",
        raw.category || "",
        raw.ownerUserId || "",
        raw.ownerCharacterId || "",
        data.length,
        data.slice(-18),
      ].join(":");
    })
    .join("|");
}

function mergeIncomingMediaPreservingUnsavedLocal(
  incoming,
  localCurrent,
  lastSavedFingerprint = ""
) {
  const cloud =
    incoming &&
    typeof incoming === "object"
      ? incoming
      : {};

  const local =
    localCurrent &&
    typeof localCurrent === "object"
      ? localCurrent
      : {};

  /*
   * Csak akkor őrzünk lokális plusz ID-kat, ha ténylegesen van
   * még el nem mentett média-változás ezen az eszközön.
   *
   * Ez megakadályozza azt a race conditiont, amikor:
   * 1. feltöltesz egy képet,
   * 2. azonnal posztolod,
   * 3. még az 1.5s media autosave előtt lefut egy cloud refresh,
   * 4. a szerver régebbi médiatára letörli a friss lokális képet.
   */
  const localDirty =
    mediaFingerprint(local) !==
    String(lastSavedFingerprint || "");

  if (!localDirty) {
    return cloud;
  }

  const merged = {
    ...cloud,
  };

  Object.keys(local)
    .forEach((id) => {
      if (merged[id]) {
        return;
      }

      const entry =
        normalizeMediaEntry(
          id,
          local[id]
        );

      if (
        !entry ||
        entry.status === "deleted" ||
        !entry.dataUrl
      ) {
        return;
      }

      merged[id] =
        local[id];
    });

  return merged;
}

async function serverLoadMedia() {
  const data =
    await apiJson(
      "/media/load",
      {
        method: "GET",
      }
    );

  return {
    media:
      data &&
      data.media &&
      typeof data.media === "object"
        ? data.media
        : {},

    syncRev:
      Math.max(
        0,
        Math.floor(
          Number(
            data &&
            data.syncRev
          ) || 0
        )
      ),
  };
}

async function serverSaveMedia(
  media,
  syncRev
) {
  return apiJson(
    "/media/save",
    {
      method: "POST",
      body: JSON.stringify({
        media:
          media || {},
        syncRev:
          Math.max(
            0,
            Math.floor(
              Number(syncRev) || 0
            )
          ),
      }),
    }
  );
}

function parseStoredMedia(txt) {
  if (!txt) return {};

  try {
    const parsed =
      JSON.parse(txt);

    return (
      parsed &&
      typeof parsed === "object" &&
      !Array.isArray(parsed)
        ? parsed
        : {}
    );
  } catch (e) {
    return {};
  }
}

function referencedMediaIds(world) {
  return new Set(
    Object.keys(
      (
        world &&
        world.images
      ) || {}
    )
  );
}

async function cacheMediaLocally(
  code,
  media
) {
  try {
    await writeBigScoped(
      MKEY(code),
      JSON.stringify(
        media || {}
      ),
      false
    );

    return true;
  } catch (e) {
    console.warn(
      "Local media cache failed:",
      e
    );

    return false;
  }
}

/*
 * CLOUD-FIRST média betöltés.
 *
 * Online: PostgreSQL az authoritative kép-tár.
 * Régi helyi képből csak olyan ID-t migrálunk vissza,
 * amelyre az authoritative world.images ténylegesen hivatkozik.
 * Így egy régi böngészőcache nem tud törölt/stale képeket
 * véletlenül visszaönteni a felhőbe.
 *
 * Offline: helyi emergency cache használható.
 */
async function loadMedia(
  code,
  world
) {
  const localTxt =
    await readBigScoped(
      MKEY(code),
      false
    );

  const legacyTxt =
    await readBig(
      MKEY(code)
    );

  const localMedia =
    parseStoredMedia(
      localTxt
    );

  const legacyMedia =
    parseStoredMedia(
      legacyTxt
    );

  const offline =
    typeof navigator !== "undefined" &&
    navigator.onLine === false;

  if (offline) {
    const fallback = {
      ...legacyMedia,
      ...localMedia,
    };

    await cacheMediaLocally(
      code,
      fallback
    );

    return {
      media: fallback,
      syncRev: 0,
      mode: "local",
    };
  }

  let cloud;

  try {
    cloud =
      await serverLoadMedia();
  } catch (e) {
    console.warn(
      "Cloud media load failed:",
      e
    );

    const fallback = {
      ...legacyMedia,
      ...localMedia,
    };

    await cacheMediaLocally(
      code,
      fallback
    );

    return {
      media: fallback,
      syncRev: 0,
      mode: "local",
      error: e,
    };
  }

  let cloudMedia = {
    ...(
      cloud &&
      cloud.media
        ? cloud.media
        : {}
    ),
  };

  let cloudSyncRev =
    Math.max(
      0,
      Math.floor(
        Number(
          cloud &&
          cloud.syncRev
        ) || 0
      )
    );

  /*
   * Egyszeri, biztonságos legacy media migráció.
   */
  const referenced =
    referencedMediaIds(world);

  const legacyPool = {
    ...legacyMedia,
    ...localMedia,
  };

  const missingReferenced = {};

  Object.keys(
    legacyPool
  ).forEach((id) => {
    if (
      referenced.has(id) &&
      !cloudMedia[id]
    ) {
      missingReferenced[id] =
        legacyPool[id];
    }
  });

  if (
    Object.keys(
      missingReferenced
    ).length
  ) {
    const candidate = {
      ...cloudMedia,
      ...missingReferenced,
    };

    try {
      const saved =
        await serverSaveMedia(
          candidate,
          cloudSyncRev
        );

      if (
        saved &&
        saved.media
      ) {
        cloudMedia =
          saved.media;

        cloudSyncRev =
          Math.max(
            0,
            Math.floor(
              Number(
                saved.syncRev
              ) || 0
            )
          );
      }
    } catch (e) {
      if (
        e &&
        e.status === 409 &&
        e.data
      ) {
        const serverMedia =
          e.data.media &&
          typeof e.data.media === "object"
            ? e.data.media
            : {};

        const merged = {
          ...candidate,
          ...serverMedia,
        };

        try {
          const retry =
            await serverSaveMedia(
              merged,
              Number(
                e.data.serverSyncRev
              ) || 0
            );

          cloudMedia =
            retry &&
            retry.media
              ? retry.media
              : merged;

          cloudSyncRev =
            Math.max(
              0,
              Math.floor(
                Number(
                  retry &&
                  retry.syncRev
                ) ||
                Number(
                  e.data.serverSyncRev
                ) || 0
              )
            );
        } catch (retryError) {
          console.warn(
            "Legacy media migration conflict retry failed:",
            retryError
          );
        }
      } else {
        console.warn(
          "Legacy media migration failed:",
          e
        );
      }
    }
  }

  await cacheMediaLocally(
    code,
    cloudMedia
  );

  return {
    media:
      cloudMedia,
    syncRev:
      cloudSyncRev,
    mode:
      "cloud",
  };
}

/*
 * Revision-aware média autosave.
 *
 * Konfliktusnál a szerver meglévő image ID-je nyer,
 * az ezen az eszközön létrejött ÚJ image ID-k viszont
 * megmaradnak és egyszer újrapróbáljuk a mentést.
 */
async function saveMedia(
  code,
  media,
  expectedSyncRev = 0
) {
  const safeMedia =
    media &&
    typeof media === "object"
      ? media
      : {};

  await cacheMediaLocally(
    code,
    safeMedia
  );

  const offline =
    typeof navigator !== "undefined" &&
    navigator.onLine === false;

  if (offline) {
    return {
      ok: true,
      mode: "local",
      media:
        safeMedia,
      syncRev:
        Math.max(
          0,
          Math.floor(
            Number(
              expectedSyncRev
            ) || 0
          )
        ),
    };
  }

  try {
    const saved =
      await serverSaveMedia(
        safeMedia,
        expectedSyncRev
      );

    return {
      ok: true,
      mode: "cloud",
      media:
        saved &&
        saved.media
          ? saved.media
          : safeMedia,
      syncRev:
        Math.max(
          0,
          Math.floor(
            Number(
              saved &&
              saved.syncRev
            ) || 0
          )
        ),
    };
  } catch (e) {
    if (
      e &&
      e.status === 409 &&
      e.data
    ) {
      const serverMedia =
        e.data.media &&
        typeof e.data.media === "object"
          ? e.data.media
          : {};

      /*
       * Server wins on an existing ID; unique local uploads survive.
       */
      const reconciled = {
        ...safeMedia,
        ...serverMedia,
      };

      try {
        const retry =
          await serverSaveMedia(
            reconciled,
            Number(
              e.data.serverSyncRev
            ) || 0
          );

        const finalMedia =
          retry &&
          retry.media
            ? retry.media
            : reconciled;

        await cacheMediaLocally(
          code,
          finalMedia
        );

        return {
          ok: true,
          mode: "cloud",
          media:
            finalMedia,
          syncRev:
            Math.max(
              0,
              Math.floor(
                Number(
                  retry &&
                  retry.syncRev
                ) ||
                Number(
                  e.data.serverSyncRev
                ) || 0
              )
            ),
          reconciled: true,
        };
      } catch (retryError) {
        return {
          ok: false,
          mode: "local",
          media:
            safeMedia,
          syncRev:
            expectedSyncRev,
          error:
            retryError,
        };
      }
    }

    return {
      ok: false,
      mode: "local",
      media:
        safeMedia,
      syncRev:
        expectedSyncRev,
      error: e,
    };
  }
}

async function dropMedia(code) {
  await dropBigScoped(MKEY(code), false);
  return dropBig(MKEY(code));
}

