function popupCombinedImpact(w,choice){
  const base=popupToneImpact(choice&&choice.tone);
  const extra=choice&&choice.socialImpact&&typeof choice.socialImpact==="object"?choice.socialImpact:{};
  const clampLocal=(n,min,max)=>Math.max(min,Math.min(max,Number(n)||0));
  const followerRate=clampLocal((Number(base.followerRate)||0)+(Number(extra.followerRate)||0),-0.02,0.02);
  const audience=Math.max(1,displayFollowerCount(w,w.meId));
  return{
    aura:clampLocal((Number(base.aura)||0)+(Number(extra.aura)||0),-14,14),
    reputation:clampLocal((Number(base.reputation)||0)+(Number(extra.reputation)||0),-18,18),
    hype:clampLocal((Number(base.hype)||0)+(Number(extra.hype)||0),-20,24),
    humor:clampLocal((Number(base.humor)||0)+(Number(extra.humor)||0),-12,12),
    followerRate,
    followers:Math.round(audience*followerRate),
  };
}

function popupEventGossipEligible(event,visibility,witnessIds,gossipPotential){
  if(!event)return false;
  if(visibility==="public")return gossipPotential>=18;
  if(visibility==="limited")return (witnessIds||[]).length>=1&&gossipPotential>=28;
  return false;
}

function resolvePopupEvent(w,eventId,choiceId){
  const event=(w.popupEvents||[]).find((e)=>e&&e.id===eventId);if(!event||event.resolved)return false;
  const choice=(event.choices||[]).find((c)=>c&&c.id===choiceId);if(!choice)return false;
  const impact=popupCombinedImpact(w,choice);
  applyExplicitSocialImpact(w,w.meId,{aura:impact.aura,reputation:impact.reputation,hype:impact.hype,humor:impact.humor,followers:impact.followers});
  applyChanges(
    w,
    (choice.reactions || []).map((r) => ({
      a:r&&r.id?r.id:"",b:w.meId,delta:Number(r&&r.delta)||0,mood:r&&r.mood,why:r&&r.why,
    }))
  );

  const visibility=["public","limited","private"].includes(event.visibility)?event.visibility:"limited";
  const witnessIds=visibility==="private"?[]:(event.witnessIds||[]).filter(Boolean).slice(0,4);
  const gossipPotential=Math.max(0,Math.min(100,Number(event.gossipPotential)||0));
  const gossipEligible=popupEventGossipEligible(event,visibility,witnessIds,gossipPotential);
  const ps=choice.publicSentiment&&typeof choice.publicSentiment==="object"?choice.publicSentiment:{};
  const cancelRisk=(Number(ps.cancel)||0)>=12||(Number(ps.controversy)||0)>=28;
  const participantIds=[...(event.involvedIds||[]),w.meId].filter((id,index,arr)=>id&&arr.indexOf(id)===index);

  event.resolved=true;
  event.resolvedAt=now();
  event.choiceId=choice.id;
  event.choiceTone=choice.tone;
  event.socialImpact={aura:impact.aura,reputation:impact.reputation,hype:impact.hype,humor:impact.humor,followers:impact.followers};
  event.publicSentiment={...ps};
  event.gossipEligible=gossipEligible;

  recordSocialEvent(w,{
    type:"popup-choice",
    refId:`${event.id}:${choice.id}`,
    ts:event.resolvedAt,
    actorId:w.meId,
    targetIds:(event.involvedIds||[]).filter(Boolean),
    witnessIds,
    visibility,
    factLevel:"observed",
    importance:Math.min(100,36+Math.round(gossipPotential*0.32)),
    drama:Math.min(100,Math.max(0,impact.hype*3)+Math.round(gossipPotential*0.35)),
    romance:event.eventKind==="romance"?Math.min(75,20+Math.round(gossipPotential*0.3)):0,
    embarrassment:Math.min(100,(choice.tone==="apologize"?4:0)+Math.round((Number(ps.dislike)||0)*0.28)),
    source:"popup-event",
    text:`${event.title}: ${event.text} → ${choice.label}`,
    tags:[
      "popup-event","choice",choice.tone,event.eventKind||"social",
      ...(gossipEligible&&gossipPotential>=45?["gossip-worthy-thread"]:[]),
      ...(cancelRisk?["controversy","backlash-risk"]:[]),
    ],
    meta:{
      popupEventId:event.id,choiceId:choice.id,location:event.location||"",gossipEligible,witnessCount:witnessIds.length,participantIds,
      gossipPotential,publicSentiment:{support:Number(ps.support)||0,dislike:Number(ps.dislike)||0,controversy:Number(ps.controversy)||0,cancel:Number(ps.cancel)||0},
      sentimentTargetIds:[w.meId],choiceImpact:{aura:impact.aura,reputation:impact.reputation,hype:impact.hype,humor:impact.humor,followers:impact.followers},
    }
  });
  return true;
}

function resolvePopupCustomResponse(w,eventId,customText,outcomeRaw){
  const event=(w.popupEvents||[]).find((e)=>e&&e.id===eventId);if(!event||event.resolved)return false;
  const outcome=normalizePopupCustomOutcome(w,event,customText,outcomeRaw);if(!outcome)return false;
  const audience=Math.max(1,displayFollowerCount(w,w.meId));
  const followerDelta=Math.round(audience*(Number(outcome.socialImpact.followerRate)||0));
  applyExplicitSocialImpact(w,w.meId,{
    aura:outcome.socialImpact.aura,reputation:outcome.socialImpact.reputation,hype:outcome.socialImpact.hype,humor:outcome.socialImpact.humor,followers:followerDelta,
  });
  applyChanges(w,(outcome.reactions||[]).map((r)=>({a:r.id,b:w.meId,delta:r.delta,mood:r.mood,why:r.why})));

  const visibility=outcome.visibility;
  const witnessIds=outcome.witnessIds||[];
  const gossipEligible=popupEventGossipEligible(event,visibility,witnessIds,outcome.gossipPotential);
  const participantIds=[...(event.involvedIds||[]),w.meId].filter((id,index,arr)=>id&&arr.indexOf(id)===index);
  const risk=publicCancelRiskSignals(outcome.customText);
  const publicSentiment={
    support:Math.max(Number(outcome.publicSentiment.support)||0,Number(risk.publicSentiment.support)||0),
    dislike:Math.max(Number(outcome.publicSentiment.dislike)||0,Number(risk.publicSentiment.dislike)||0),
    controversy:Math.max(Number(outcome.publicSentiment.controversy)||0,Number(risk.publicSentiment.controversy)||0),
    cancel:Math.max(Number(outcome.publicSentiment.cancel)||0,Number(risk.publicSentiment.cancel)||0),
  };
  const cancelRisk=publicSentiment.cancel>=12||publicSentiment.controversy>=28;

  event.resolved=true;
  event.resolvedAt=now();
  event.choiceId="custom";
  event.choiceTone=outcome.tone;
  event.customResponse=outcome.customText;
  event.customOutcome=outcome.summary;
  event.visibility=visibility;
  event.witnessIds=witnessIds;
  event.gossipPotential=outcome.gossipPotential;
  event.gossipEligible=gossipEligible;
  event.socialImpact={...outcome.socialImpact,followers:followerDelta};
  event.publicSentiment=publicSentiment;

  recordSocialEvent(w,{
    type:"popup-choice",
    refId:`${event.id}:custom`,
    ts:event.resolvedAt,
    actorId:w.meId,
    targetIds:(event.involvedIds||[]).filter(Boolean),
    witnessIds,
    visibility,
    factLevel:"observed",
    importance:Math.min(100,42+Math.round(outcome.gossipPotential*0.35)),
    drama:Math.max(outcome.drama,Math.round(publicSentiment.controversy*0.7)),
    romance:outcome.romance,
    embarrassment:Math.max(outcome.embarrassment,risk.embarrassment),
    source:"popup-event",
    text:`${event.title}: ${outcome.summary||outcome.customText}`,
    tags:[
      "popup-event","custom-response",outcome.tone,event.eventKind||"social",...outcome.tags,...risk.tags,
      ...(gossipEligible&&outcome.gossipPotential>=45?["gossip-worthy-thread"]:[]),
      ...(cancelRisk?["controversy","backlash-risk"]:[]),
    ],
    meta:{
      popupEventId:event.id,choiceId:"custom",location:event.location||"",gossipEligible,witnessCount:witnessIds.length,participantIds,gossipPotential:outcome.gossipPotential,
      publicSentiment,sentimentTargetIds:[w.meId],customResponse:outcome.customText,
      socialImpact:{aura:outcome.socialImpact.aura,reputation:outcome.socialImpact.reputation,hype:outcome.socialImpact.hype,humor:outcome.socialImpact.humor,followers:followerDelta},
    }
  });
  return true;
}

function snoozePopupEvent(w,eventId){const e=(w.popupEvents||[]).find((x)=>x&&x.id===eventId);if(e&&!e.resolved){e.snoozedAt=now();return true;}return false;}

/* ============================================================
   SOCIAL STATS ENGINE
   ============================================================ */

/*
 * A social médiában látható számok és a játékbeli társadalmi
 * állapot külön dolgok.
 *
 * - followers/following: tényleges profiladat
 * - followerPower: a követőszám 0–100 logaritmikus social ereje
 * - popularity: követőszám + tartós engagement
 * - aura: core aura + követőszám social leverage
 * - reputation: core reputation + kisebb követőszám-hatás
 * - humor: core humor + enyhe követőszám-hatás
 * - hype: friss események + követőszám alap-buzz
 * - clout: követőszám + popularity + aura + hype + reputation + humor összesített befolyása
 *
 * Nem kap valaki automatikusan +reputation pontot csak azért,
 * mert kommenteltek neki. A figyelem és a jó hírnév nem ugyanaz.
 */

function clampSignedSocial(value) {
  const n = Number(value);

  if (!Number.isFinite(n)) {
    return 0;
  }

  return Math.max(
    -100,
    Math.min(
      100,
      Math.round(n * 10) / 10
    )
  );
}

function clampPositiveSocial(value) {
  const n = Number(value);

  if (!Number.isFinite(n)) {
    return 0;
  }

  return Math.max(
    0,
    Math.min(
      100,
      Math.round(n * 10) / 10
    )
  );
}

function defaultSocialStatsRow() {
  return {
    /*
     * A felületen látható, DERIVED értékek.
     */
    aura: 0,
    popularity: 0,
    reputation: 0,
    hype: 0,
    humor: 0,
    clout: 0,

    /*
     * Tartalmi / történeti alapértékek.
     *
     * Ezeket módosítják a gossip, popup, virality stb.
     * A követőszám bónusza NEM ide íródik, így refreshkor
     * nem halmozódik újra és újra.
     */
    auraCore: 0,
    reputationCore: 0,
    humorCore: 0,

    /*
     * A hype eseményalapú és időérzékeny.
     * Az explicit +/- módosítás 24 óra alatt kifut.
     */
    hypeModifier: 0,
    hypeModifierAt: 0,

    /*
     * Követőszámból számolt 0–100 social power.
     */
    followerPower: 0,

    followers: 0,
    following: 0,

    signals: {
      posts: 0,
      likesReceived: 0,
      commentsReceived: 0,
      repostsReceived: 0,
      knownFollowers: 0,
    },

    sentiment: {
      support: 0,
      dislike: 0,
      controversy: 0,
      stanEnergy: 0,
      cancelPressure: 0,
    },

    fanbase: {
      coreFans: 0,
      activeStans: 0,
      skeptics: 0,
      antis: 0,
    },

    viralPosts: 0,

    updatedAt: 0,
  };
}

function ensureSocialStatsFor(
  w,
  characterId
) {
  if (
    !w ||
    !characterId
  ) {
    return null;
  }

  if (
    !w.socialStats ||
    typeof w.socialStats !== "object" ||
    Array.isArray(w.socialStats)
  ) {
    w.socialStats = {};
  }

  const id =
    String(characterId);

  const current =
    w.socialStats[id] &&
    typeof w.socialStats[id] === "object" &&
    !Array.isArray(w.socialStats[id])
      ? w.socialStats[id]
      : {};

  const base =
    defaultSocialStatsRow();

  const row = {
    ...base,
    ...current,

    signals: {
      ...base.signals,
      ...(
        current.signals &&
        typeof current.signals === "object" &&
        !Array.isArray(current.signals)
          ? current.signals
          : {}
      ),
    },

    sentiment: {
      ...base.sentiment,
      ...(
        current.sentiment &&
        typeof current.sentiment === "object" &&
        !Array.isArray(current.sentiment)
          ? current.sentiment
          : {}
      ),
    },

    fanbase: {
      ...base.fanbase,
      ...(
        current.fanbase &&
        typeof current.fanbase === "object" &&
        !Array.isArray(current.fanbase)
          ? current.fanbase
          : {}
      ),
    },
  };

  /*
   * Régi world migráció:
   * az eddigi látható aura/reputation/humor érték legyen
   * az első "core", így semmi nem vész el.
   *
   * Ha a core már létezik, onnantól azt tartjuk meg.
   */
  row.auraCore =
    Object.prototype.hasOwnProperty.call(
      current,
      "auraCore"
    )
      ? clampSignedSocial(
          current.auraCore
        )
      : clampSignedSocial(
          current.aura
        );

  row.reputationCore =
    Object.prototype.hasOwnProperty.call(
      current,
      "reputationCore"
    )
      ? clampSignedSocial(
          current.reputationCore
        )
      : clampSignedSocial(
          current.reputation
        );

  row.humorCore =
    Object.prototype.hasOwnProperty.call(
      current,
      "humorCore"
    )
      ? clampSignedSocial(
          current.humorCore
        )
      : clampSignedSocial(
          current.humor
        );

  row.hypeModifier =
    clampSignedSocial(
      row.hypeModifier
    );

  row.hypeModifierAt =
    Math.max(
      0,
      Number(
        row.hypeModifierAt
      ) || 0
    );

  row.followerPower =
    clampPositiveSocial(
      row.followerPower
    );

  row.clout =
    clampPositiveSocial(
      row.clout
    );

  row.aura =
    clampSignedSocial(
      row.aura
    );

  row.reputation =
    clampSignedSocial(
      row.reputation
    );

  row.humor =
    clampSignedSocial(
      row.humor
    );

  row.popularity =
    clampPositiveSocial(
      row.popularity
    );

  row.hype =
    clampPositiveSocial(
      row.hype
    );

  row.followers =
    Math.max(
      0,
      Math.round(
        Number(row.followers) || 0
      )
    );

  row.following =
    Math.max(
      0,
      Math.round(
        Number(row.following) || 0
      )
    );

  row.sentiment.support =
    clampPositiveSocial(
      row.sentiment.support
    );

  row.sentiment.dislike =
    clampPositiveSocial(
      row.sentiment.dislike
    );

  row.sentiment.controversy =
    clampPositiveSocial(
      row.sentiment.controversy
    );

  row.sentiment.stanEnergy =
    clampPositiveSocial(
      row.sentiment.stanEnergy
    );

  row.sentiment.cancelPressure =
    clampPositiveSocial(
      row.sentiment.cancelPressure
    );

  ["coreFans", "activeStans", "skeptics", "antis"].forEach((key) => {
    row.fanbase[key] = Math.max(0, Math.round(Number(row.fanbase[key]) || 0));
  });

  row.viralPosts =
    Math.max(
      0,
      Math.round(
        Number(row.viralPosts) || 0
      )
    );

  row.updatedAt =
    Number(row.updatedAt) || 0;

  w.socialStats[id] = row;

  return row;
}

/*
 * Követőszámból kiinduló ismertségi alap.
 *
 * Logaritmikus skála kell, mert 1 000 -> 10 000 követő között
 * társadalmilag sokkal nagyobb a különbség, mint pusztán +9000.
 *
 * Körülbelül:
 * 10 követő      -> 16
 * 100            -> 32
 * 1 000          -> 48
 * 10 000         -> 64
 * 100 000        -> 80
 * 1 000 000      -> 96
 */
function followerPopularityBase(
  followers
) {
  const n =
    Math.max(
      0,
      Number(followers) || 0
    );

  if (!n) return 0;

  return clampPositiveSocial(
    Math.log10(
      n + 1
    ) * 16
  );
}

/*
 * Ugyanazt a logaritmikus követőskálát használjuk
 * "social power"-ként is.
 *
 * Ez azért jó, mert:
 * - 100 -> kb. 32
 * - 1K  -> kb. 48
 * - 10K -> kb. 64
 * - 100K -> kb. 80
 * - 1M -> kb. 96
 *
 * Tehát a követőszám nagyon számít, de 1 millió után
 * sem robban végtelenre.
 */
function followerSocialPower(
  followers
) {
  return followerPopularityBase(
    followers
  );
}

/*
 * CLOUT = összesített társadalmi befolyás.
 *
 * A követőszám a legerősebb komponens,
 * de a jó aura, popularity, hype, reputation és humor
 * ténylegesen tovább emeli.
 *
 * Így két azonos követőszámú karakter közül annak lesz
 * nagyobb cloutja, akinek a többi social statja is erősebb.
 */
function socialCloutScore(
  row,
  followerPower
) {
  if (!row) return 0;

  const fp =
    clampPositiveSocial(
      followerPower
    );

  const popularity =
    clampPositiveSocial(
      row.popularity
    );

  const hype =
    clampPositiveSocial(
      row.hype
    );

  const aura =
    Math.max(
      0,
      clampSignedSocial(
        row.aura
      )
    );

  const reputation =
    Math.max(
      0,
      clampSignedSocial(
        row.reputation
      )
    );

  const humor =
    Math.max(
      0,
      clampSignedSocial(
        row.humor
      )
    );

  return clampPositiveSocial(
    fp * 0.50 +
    popularity * 0.20 +
    aura * 0.12 +
    hype * 0.08 +
    reputation * 0.06 +
    humor * 0.04
  );
}

/*
 * Követőszám-bónusz a külön social statokhoz.
 *
 * Nem ugyanannyit ad mindenhez:
 * - aura: erősen számít a social presence
 * - hype: nagy közönség önmagában is ad alap buzz-t
 * - reputation: enyhébben számít
 * - humor: csak kis mértékben, mert sok követő != automatikusan vicces
 */
function followerDerivedSocialBoost(
  followerPower
) {
  const fp =
    clampPositiveSocial(
      followerPower
    );

  return {
    aura:
      fp * 0.25,

    reputation:
      fp * 0.10,

    humor:
      fp * 0.06,

    hype:
      fp * 0.20,
  };
}

/*
 * Az explicit hype +/- hatás 24 óra alatt fokozatosan kifut.
 */
function liveHypeModifier(
  row
) {
  if (!row) return 0;

  const value =
    Number(
      row.hypeModifier
    ) || 0;

  const at =
    Number(
      row.hypeModifierAt
    ) || 0;

  if (!value || !at) {
    return 0;
  }

  const age =
    Math.max(
      0,
      now() - at
    );

  const life =
    24 * 3600e3;

  if (age >= life) {
    return 0;
  }

  return (
    value *
    (
      1 -
      age / life
    )
  );
}


function socialSignalsFor(
  w,
  characterId
) {
  const posts =
    (w.posts || []).filter(
      (p) =>
        p &&
        p.authorId ===
          characterId
    );

  let likesReceived = 0;
  let commentsReceived = 0;
  let repostsReceived = 0;

  posts.forEach((post) => {
    likesReceived +=
      Math.max(
        0,
        Number(post.likes) || 0
      );

    commentsReceived +=
      safePostComments(post).filter(
        (c) =>
          c &&
          c.authorId !==
            characterId
      ).length;

    repostsReceived +=
      repostCount(
        w,
        post.id
      );
  });

  const profile =
    socialProfileById(
      w,
      characterId
    );

  const knownFollowers =
    profile
      ? knownFollowerCount(
          w,
          characterId
        )
      : 0;

  return {
    posts:
      posts.length,

    likesReceived,

    commentsReceived,

    repostsReceived,

    knownFollowers,
  };
}

/*
 * A HYPE időérzékeny.
 *
 * Egy régi like nem tart valakit örökké felkapott állapotban.
 * A Social Event Ledger elmúlt 24 órája adja a fő impulzust,
 * és az újabb esemény többet ér, mint a régebbi.
 */
function recentHypeFor(
  w,
  characterId
) {
  const cutoff =
    now() -
    24 * 3600e3;

  let heat = 0;

  (w.socialEvents || []).forEach(
    (event) => {
      if (
        !event ||
        Number(event.ts) <
          cutoff
      ) {
        return;
      }

      const actorHit =
        event.actorId ===
          characterId;

      const targetHit =
        Array.isArray(
          event.targetIds
        ) &&
        event.targetIds.includes(
          characterId
        );

      if (
        !actorHit &&
        !targetHit
      ) {
        return;
      }

      const ageHours =
        Math.max(
          0,
          (
            now() -
            Number(event.ts)
          ) /
            3600e3
        );

      /*
       * 24 óra alatt fokozatosan halványul.
       */
      const freshness =
        Math.max(
          0.08,
          1 -
            ageHours / 24
        );

      let weight = 0;

      if (
        event.type ===
          "post" &&
        actorHit
      ) {
        weight = 1.5;
      }

      if (
        event.type ===
          "like" &&
        targetHit
      ) {
        weight = 0.7;
      }

      if (
        (
          event.type ===
            "comment" ||
          event.type ===
            "reply"
        ) &&
        targetHit
      ) {
        weight = 1.8;
      }

      if (
        event.type ===
          "repost" &&
        targetHit
      ) {
        weight = 4;
      }

      if (
        event.type ===
          "follow" &&
        targetHit
      ) {
        weight = 2.2;
      }

      /*
       * Az unfollow is figyelem / social mozgás.
       * Később a reputation/cancel dönti el,
       * hogy ez negatív-e; itt csak hype.
       */
      if (
        event.type ===
          "unfollow" &&
        targetHit
      ) {
        weight = 2.8;
      }

      if (
        event.type ===
          "viral" &&
        actorHit
      ) {
        weight = 9;
      }

      if (
        event.type ===
          "cancel-wave" &&
        (
          actorHit ||
          targetHit
        )
      ) {
        weight = 10;
      }

      if (
        event.type ===
          "stan-wave" &&
        (
          actorHit ||
          targetHit
        )
      ) {
        weight = 8;
      }

      heat +=
        weight *
        freshness;
    }
  );

  /*
   * Kis szereplőgárdánál is legyen érzékelhető,
   * de ne érje el két like-kal a 100-at.
   */
  return clampPositiveSocial(
    heat * 4
  );
}


function publicSentimentFor(
  w,
  characterId
) {
  const cutoff =
    now() -
    72 * 3600e3;

  let supportHeat = 0;
  let dislikeHeat = 0;
  let controversyHeat = 0;
  let explicitStan = 0;
  let explicitCancel = 0;

  const supporterActions = {};

  (w.socialEvents || []).forEach(
    (event) => {
      if (
        !event ||
        Number(event.ts) <
          cutoff
      ) {
        return;
      }

      const targetHit =
        Array.isArray(
          event.targetIds
        ) &&
        event.targetIds.includes(
          characterId
        );

      const actorHit =
        event.actorId ===
          characterId;

      if (
        !targetHit &&
        !actorHit
      ) {
        return;
      }

      const ageHours =
        Math.max(
          0,
          (
            now() -
            Number(event.ts)
          ) /
            3600e3
        );

      const freshness =
        Math.max(
          0.12,
          1 -
            ageHours / 72
        );

      /*
       * Támogató jelek.
       * Ezek figyelmet / támogatást jeleznek,
       * de NEM automatikusan jó reputationt.
       */
      if (
        targetHit &&
        event.type === "like"
      ) {
        supportHeat +=
          0.8 * freshness;
      }

      if (
        targetHit &&
        event.type === "repost"
      ) {
        supportHeat +=
          2.5 * freshness;
      }

      if (
        targetHit &&
        event.type === "follow"
      ) {
        supportHeat +=
          1.7 * freshness;
      }

      /*
       * Unfollow már valódi negatív social jel.
       */
      if (
        targetHit &&
        event.type === "unfollow"
      ) {
        dislikeHeat +=
          2.6 * freshness;
      }

      /*
       * A nyilvános kommentek nem automatikusan pozitívak.
       * A kommentelő meglévő kapcsolata segít eldönteni,
       * hogy inkább támogatói vagy ellenséges social jelről van szó.
       *
       * Ez nem "szövegelemzés": csak társas kontextus.
       */
      if (
        targetHit &&
        event.actorId &&
        event.actorId !==
          characterId &&
        (
          event.type ===
            "comment" ||
          event.type ===
            "reply"
        )
      ) {
        const commentRel =
          getRel(
            w,
            event.actorId,
            characterId
          );

        const commentRelScore =
          Number(
            commentRel &&
            commentRel.score
          ) || 0;

        if (
          commentRelScore >= 25
        ) {
          supportHeat +=
            1.3 * freshness;
        } else if (
          commentRelScore <= -20
        ) {
          dislikeHeat +=
            1.6 * freshness;

          controversyHeat +=
            0.8 * freshness;
        } else {
          controversyHeat +=
            0.25 * freshness;
        }
      }

      /*
       * Későbbi gossip / cancel / popup rendszerek
       * explicit sentimentet is adhatnak.
       */
      const publicSentiment =
        event.meta &&
        event.meta.publicSentiment &&
        typeof event.meta.publicSentiment ===
          "object"
          ? event.meta.publicSentiment
          : null;

      const sentimentTargetIds = event.meta && Array.isArray(event.meta.sentimentTargetIds)
        ? event.meta.sentimentTargetIds
        : [];
      const sentimentAppliesHere = !sentimentTargetIds.length || sentimentTargetIds.includes(characterId);

      if (publicSentiment && sentimentAppliesHere) {
        supportHeat +=
          Math.max(
            0,
            Number(
              publicSentiment.support
            ) || 0
          ) *
          0.18 *
          freshness;

        dislikeHeat +=
          Math.max(
            0,
            Number(
              publicSentiment.dislike
            ) || 0
          ) *
          0.18 *
          freshness;

        controversyHeat +=
          Math.max(
            0,
            Number(
              publicSentiment.controversy
            ) || 0
          ) *
          0.18 *
          freshness;

        explicitStan +=
          Math.max(
            0,
            Number(
              publicSentiment.stan
            ) || 0
          ) *
          0.18 *
          freshness;

        explicitCancel +=
          Math.max(
            0,
            Number(
              publicSentiment.cancel
            ) || 0
          ) *
          0.18 *
          freshness;
      }

      const tags =
        Array.isArray(event.tags)
          ? event.tags
          : [];

      if (
        tags.includes("stan") ||
        tags.includes("support-wave")
      ) {
        explicitStan +=
          6 * freshness;
      }

      if (
        tags.includes("cancel") ||
        tags.includes("backlash")
      ) {
        explicitCancel +=
          7 * freshness;
        dislikeHeat +=
          3 * freshness;
      }

      if (
        tags.includes("controversy")
      ) {
        controversyHeat +=
          6 * freshness;
      }

      /*
       * Stan energy: ugyanaz a létező karakter többször
       * támogatja ugyanazt a személyt.
       */
      if (
        targetHit &&
        event.actorId &&
        event.actorId !==
          characterId &&
        [
          "like",
          "repost",
          "follow",
        ].includes(
          event.type
        )
      ) {
        const actorId =
          event.actorId;

        supporterActions[
          actorId
        ] =
          (
            supporterActions[
              actorId
            ] || 0
          ) + 1;
      }
    }
  );

  let repeatedSupport = 0;

  Object.values(
    supporterActions
  ).forEach((count) => {
    if (count >= 2) {
      repeatedSupport +=
        Math.min(
          4,
          count - 1
        );
    }
  });

  const support =
    clampPositiveSocial(
      supportHeat * 5
    );

  const dislike =
    clampPositiveSocial(
      dislikeHeat * 6
    );

  const stanEnergy =
    clampPositiveSocial(
      repeatedSupport * 10 +
      support * 0.28 +
      explicitStan * 4
    );

  const cancelPressure =
    clampPositiveSocial(
      dislike * 0.8 +
      explicitCancel * 4
    );

  /*
   * Controversy akkor nő igazán, ha egyszerre van
   * támogatás ÉS ellenállás / backlash.
   */
  const controversy =
    clampPositiveSocial(
      controversyHeat * 4 +
      Math.min(
        support,
        dislike
      ) *
        0.9 +
      cancelPressure *
        0.22
    );

  return {
    support,
    dislike,
    controversy,
    stanEnergy,
    cancelPressure,
  };
}

function postViralityScore(
  w,
  post
) {
  if (
    !w ||
    !post ||
    !post.id
  ) {
    return 0;
  }

  const ageHours =
    Math.max(
      0,
      (
        now() -
        (Number(post.ts) || 0)
      ) /
        3600e3
    );

  /*
   * 72 óránál régebbi poszt már ne kezdjen
   * magától hirtelen virálissá válni.
   */
  if (ageHours > 72) {
    return 0;
  }

  const audience =
    Math.max(
      25,
      displayFollowerCount(
        w,
        post.authorId
      )
    );

  const likes =
    Math.max(
      0,
      Number(post.likes) || 0
    );

  const comments =
    safePostComments(post).length;

  const reposts =
    repostCount(
      w,
      post.id
    );

  const engagement =
    likes +
    comments * 2 +
    reposts * 5;

  if (!engagement) {
    return 0;
  }

  /*
   * Kis account is tudjon virális lenni:
   * a saját közönségéhez képesti engagement erősen számít.
   */
  const rate =
    engagement /
    audience;

  const relativeScore =
    Math.min(
      56,
      rate * 420
    );

  /*
   * Nagy accountnál az abszolút számok is számítanak.
   */
  const absoluteScore =
    Math.min(
      28,
      Math.log10(
        engagement + 1
      ) * 10
    );

  /*
   * Repost a legerősebb terjedési jel.
   */
  const spreadScore =
    Math.min(
      22,
      reposts * 4.5
    );

  const freshness =
    ageHours <= 12
      ? 1
      : Math.max(
          0.58,
          1 -
            (ageHours - 12) /
              120
        );

  return clampPositiveSocial(
    (
      relativeScore +
      absoluteScore +
      spreadScore
    ) *
      freshness
  );
}

function viralityStatus(score) {
  const n =
    Number(score) || 0;

  if (n >= 82) {
    return "breakout";
  }

  if (n >= 60) {
    return "viral";
  }

  if (n >= 35) {
    return "rising";
  }

  return "normal";
}

function viralFollowerGainFor(
  w,
  post,
  score
) {
  if (!w || !post || typeof post !== "object" || !post.id) return 0;

  const audience =
    Math.max(
      25,
      displayFollowerCount(
        w,
        post.authorId
      )
    );

  const engagement =
    Math.max(
      1,
      Number(post.likes) || 0
    ) +
    safePostComments(post).length * 2 +
    repostCount(
      w,
      post.id
    ) * 5;

  const strength =
    Math.max(
      0,
      Math.min(
        1,
        (
          Number(score) -
          60
        ) /
          40
      )
    );

  /*
   * Viralitás új követőket hozhat akkor is,
   * ha később a tartalom megosztóvá válik.
   * A cancel motor majd külön tud követőket levonni.
   */
  const proportional =
    audience *
    (
      0.002 +
      strength * 0.018
    );

  const engagementFloor =
    engagement *
    (
      0.35 +
      strength * 0.45
    );

  return Math.max(
    2,
    Math.min(
      50000,
      Math.round(
        Math.max(
          proportional,
          engagementFloor
        )
      )
    )
  );
}

function refreshPostVirality(
  w,
  postId
) {
  if (
    !w ||
    !postId
  ) {
    return null;
  }

  const post =
    (w.posts || []).find(
      (p) =>
        p &&
        p.id === postId
    );

  if (!post) {
    return null;
  }

  const score =
    postViralityScore(
      w,
      post
    );

  const status =
    viralityStatus(score);

  const previous =
    post.virality &&
    typeof post.virality ===
      "object"
      ? post.virality
      : {};

  const wasViral =
    Boolean(
      previous.viralAt
    );

  post.virality = {
    ...previous,
    score,
    status,
    updatedAt: now(),
  };

  /*
   * Egy poszt csak egyszer kapja meg az első
   * virális követőnövekedést.
   */
  if (
    score >= 60 &&
    !wasViral
  ) {
    const author =
      socialProfileById(
        w,
        post.authorId
      );

    if (author) {
      ensureSocialProfileRow(
        author
      );

      const followerGain =
        viralFollowerGainFor(
          w,
          post,
          score
        );

      author.followerDelta =
        Math.round(
          Number(
            author.followerDelta
          ) || 0
        ) +
        followerGain;

      post.virality.viralAt =
        now();

      post.virality.followerGain =
        followerGain;

      /*
       * A viral event külön bekerül a ledgerbe,
       * így később a gossip / trend rendszer is látja.
       */
      recordSocialEvent(
        w,
        {
          type: "viral",

          refId:
            `viral:${post.id}`,

          ts: now(),

          actorId:
            post.authorId,

          targetIds: [],

          visibility:
            "public",

          factLevel:
            "observed",

          importance:
            status ===
              "breakout"
              ? 90
              : 72,

          drama:
            status ===
              "breakout"
              ? 30
              : 14,

          romance: 0,
          embarrassment: 0,

          source:
            "social-engine",

          text:
            "A post went viral.",

          tags: [
            "social",
            "viral",
            status,
          ],

          meta: {
            postId:
              post.id,

            viralScore:
              score,

            followerGain,

            socialImpact: {
              hype:
                status ===
                  "breakout"
                  ? 15
                  : 8,
            },
          },
        }
      );

      if (
        isHuman(
          w,
          post.authorId
        )
      ) {
        pushNote(
          w,
          post.authorId,
          {
            icon: "🔥",

            text:
              sysLangText(
                w,
                post.authorId,
                `A posztod felkapott lett. +${followerGain} követő`,
                `Your post is taking off. +${followerGain} followers`
              ),

            link: {
              type: "post",
              id: post.id,
            },
          }
        );
      }
    }
  }

  refreshSocialStatsFor(
    w,
    post.authorId
  );

  return post.virality;
}


function recentSocialWave(
  w,
  characterId,
  mode,
  hours = 6
) {
  const cutoff =
    now() -
    hours * 3600e3;

  return (
    (w.socialEvents || []).some(
      (event) =>
        event &&
        Number(event.ts) >=
          cutoff &&
        Array.isArray(
          event.targetIds
        ) &&
        event.targetIds.includes(
          characterId
        ) &&
        Array.isArray(
          event.tags
        ) &&
        event.tags.includes(
          "social-wave"
        ) &&
        event.tags.includes(
          mode
        )
    )
  );
}

function strongestSocialPostFor(
  w,
  characterId
) {
  return (
    (w.posts || [])
      .filter(
        (post) =>
          post &&
          post.authorId ===
            characterId
      )
      .slice()
      .sort((a, b) => {
        const av =
          Number(
            a.virality &&
            a.virality.score
          ) || 0;

        const bv =
          Number(
            b.virality &&
            b.virality.score
          ) || 0;

        if (av !== bv) {
          return bv - av;
        }

        return (
          (Number(b.ts) || 0) -
          (Number(a.ts) || 0)
        );
      })[0] ||
    null
  );
}

function socialSupportScore(
  w,
  actorId,
  targetId
) {
  if (
    !actorId ||
    !targetId ||
    actorId === targetId
  ) {
    return -999;
  }

  const actor =
    socialProfileById(
      w,
      actorId
    );

  const target =
    socialProfileById(
      w,
      targetId
    );

  if (
    !actor ||
    !target ||
    isHuman(w, actor.id)
  ) {
    return -999;
  }

  const rel =
    getRel(
      w,
      actor.id,
      target.id
    );

  const relScore =
    Number(rel && rel.score) ||
    0;

  let score =
    relScore;

  if (
    isFollowing(
      w,
      actor.id,
      target.id
    )
  ) {
    score += 24;
  }

  const targetPosts =
    (w.posts || [])
      .filter(
        (p) =>
          p &&
          p.authorId ===
            target.id
      )
      .slice(0, 8);

  targetPosts.forEach((p) => {
    if (
      Array.isArray(
        p.likedBy
      ) &&
      p.likedBy.includes(
        actor.id
      )
    ) {
      score += 5;
    }

    if (
      hasReposted(
        w,
        actor.id,
        p.id
      )
    ) {
      score += 10;
    }

    score += Math.min(
      10,
      safePostComments(p).filter(
        (c) =>
          c &&
          c.authorId ===
            actor.id
      ).length * 5
    );
  });

  return Math.round(score);
}

function socialCriticScore(
  w,
  actorId,
  targetId
) {
  if (
    !actorId ||
    !targetId ||
    actorId === targetId
  ) {
    return -999;
  }

  const actor =
    socialProfileById(
      w,
      actorId
    );

  const target =
    socialProfileById(
      w,
      targetId
    );

  if (
    !actor ||
    !target ||
    isHuman(w, actor.id)
  ) {
    return -999;
  }

  const rel =
    getRel(
      w,
      actor.id,
      target.id
    );

  const relScore =
    Number(rel && rel.score) ||
    0;

  /*
   * Erősen pozitív / fix családi kapcsolat ne váljon
   * automatikusan cancel-mobbá csak azért, mert trend van.
   */
  if (
    rel &&
    rel.fixed &&
    relScore > -20
  ) {
    return -999;
  }

  let score =
    -relScore;

  if (
    isFollowing(
      w,
      actor.id,
      target.id
    )
  ) {
    score += 8;
  }

  if (
    relScore <= -45
  ) {
    score += 18;
  }

  return Math.round(score);
}

function socialWaveCast(
  w,
  targetId,
  mode
) {
  const rows =
    (w.chars || [])
      .filter(
        (c) =>
          c &&
          c.id !== targetId &&
          !isHuman(w, c.id)
      )
      .map((c) => {
        const score =
          mode === "cancel"
            ? socialCriticScore(
                w,
                c.id,
                targetId
              )
            : socialSupportScore(
                w,
                c.id,
                targetId
              );

        return {
          id: c.id,
          score,
          tie: Math.random(),
        };
      })
      .filter(
        (row) =>
          row.score >
          (
            mode === "cancel"
              ? 12
              : 18
          )
      )
      .sort((a, b) => {
        if (
          a.score !== b.score
        ) {
          return (
            b.score -
            a.score
          );
        }

        return (
          a.tie -
          b.tie
        );
      });

  return rows.slice(
    0,
    3
  );
}


function gossipPressureForTarget(w, targetId) {
  const state = ensureGossipPropagationState(w);
  if (!state || !targetId) return { total: 0, negative: 0, support: 0, holders: 0, echoes: 0 };
  let total = 0, negative = 0, support = 0, holders = 0, echoes = 0;
  (state.rumors || []).forEach((rumor) => {
    if (!rumor || !(rumor.subjectIds || []).includes(targetId)) return;
    const count = Object.keys(rumor.holders || {}).length;
    const echoCount = Number(rumor.publicEchoCount || 0);
    if (count < 3 && echoCount < 1) return;
    const weight = Math.min(55, count * 5 + echoCount * 8 + Number(rumor.heat || 0) * 0.16);
    total += weight;
    holders += count;
    echoes += echoCount;
    if (gossipRumorNegative(rumor)) negative += weight;
    else if (Number(rumor.romance || 0) < 30) support += Math.max(0, weight * 0.35);
  });
  return {
    total: Math.round(total),
    negative: Math.round(negative),
    support: Math.round(support),
    holders,
    echoes,
  };
}

function pickSocialWaveAction(w) {
  refreshAllSocialStats(w);

  const candidates = [];
  const cancelThreshold = Math.max(14, 24 / LIVE_WORLD_CANCEL_SENSITIVITY);
  const gossipCancelThreshold = Math.max(9, 16 / LIVE_WORLD_CANCEL_SENSITIVITY);
  const counterCancelThreshold = Math.max(20, 32 / LIVE_WORLD_CANCEL_SENSITIVITY);
  const counterStanThreshold = Math.max(18, 24 / Math.sqrt(LIVE_WORLD_CANCEL_SENSITIVITY));

  socialProfiles(w).forEach(
    (target) => {
      if (!target) return;

      const row =
        ensureSocialStatsFor(
          w,
          target.id
        );

      if (!row) return;

      const sentiment =
        row.sentiment ||
        defaultSocialStatsRow()
          .sentiment;

      const post =
        strongestSocialPostFor(
          w,
          target.id
        );

      const gossipPressure =
        gossipPressureForTarget(
          w,
          target.id
        );

      /*
       * Counter-backlash:
       * egyszerre van komoly támadás ÉS erős védőtábor.
       */
      if (
        sentiment.cancelPressure >=
          counterCancelThreshold &&
        sentiment.stanEnergy >=
          counterStanThreshold &&
        !recentSocialWave(
          w,
          target.id,
          "counter",
          8
        )
      ) {
        candidates.push({
          targetId:
            target.id,
          mode: "counter",
          score:
            sentiment.cancelPressure +
            sentiment.stanEnergy +
            sentiment.controversy *
              0.5 +
            gossipPressure.negative * 0.55,
          postId:
            post && post.id,
        });
      }

      if (
        sentiment.cancelPressure >=
          cancelThreshold &&
        gossipPressure.negative >=
          gossipCancelThreshold &&
        !recentSocialWave(
          w,
          target.id,
          "cancel",
          8
        )
      ) {
        candidates.push({
          targetId:
            target.id,
          mode: "cancel",
          score:
            sentiment.cancelPressure *
              1.35 +
            sentiment.controversy +
            gossipPressure.negative * 0.8,
          postId:
            post && post.id,
        });
      }

      if (
        (
          sentiment.stanEnergy >=
            24 ||
          (
            row.hype >= 55 &&
            sentiment.support >=
              30
          )
        ) &&
        !recentSocialWave(
          w,
          target.id,
          "stan",
          8
        )
      ) {
        candidates.push({
          targetId:
            target.id,
          mode: "stan",
          score:
            sentiment.stanEnergy *
              1.25 +
            row.hype * 0.45 +
            sentiment.support *
              0.35,
          postId:
            post && post.id,
        });
      }
    }
  );

  candidates.sort(
    (a, b) =>
      b.score - a.score
  );

  const best =
    candidates[0];

  if (!best) return null;

  const cast =
    socialWaveCast(
      w,
      best.targetId,
      best.mode === "cancel"
        ? "cancel"
        : "support"
    );

  if (!cast.length) {
    return null;
  }

  return {
    ...best,
    cast,
  };
}

function waveBackgroundFollowerDelta(
  w,
  targetId,
  mode,
  strength
) {
  const audience =
    Math.max(
      25,
      displayFollowerCount(
        w,
        targetId
      )
    );

  const normalized =
    Math.max(
      0,
      Math.min(
        1,
        (
          Number(strength) ||
          0
        ) / 100
      )
    );

  if (mode === "cancel") {
    return -Math.max(
      2,
      Math.min(
        50000,
        Math.round(
          audience *
          (
            0.002 +
            normalized *
              0.018
          )
        )
      )
    );
  }

  if (mode === "counter") {
    return Math.max(
      1,
      Math.min(
        25000,
        Math.round(
          audience *
          (
            0.001 +
            normalized *
              0.009
          )
        )
      )
    );
  }

  return Math.max(
    1,
    Math.min(
      30000,
      Math.round(
        audience *
        (
          0.001 +
          normalized *
            0.012
        )
      )
    )
  );
}

function refreshSocialStatsFor(
  w,
  characterId
) {
  const profile =
    socialProfileById(
      w,
      characterId
    );

  if (!profile) {
    return null;
  }

  const row =
    ensureSocialStatsFor(
      w,
      characterId
    );

  if (!row) return null;

  const followers =
    displayFollowerCount(
      w,
      characterId
    );

  const following =
    displayFollowingCount(
      w,
      characterId
    );

  const signals =
    socialSignalsFor(
      w,
      characterId
    );

  /*
   * Tartós engagement-bónusz.
   *
   * Ez NEM reputation.
   * Egy botrányos ember is lehet nagyon népszerű.
   */
  const engagementTotal =
    signals.likesReceived +
    signals.commentsReceived * 2 +
    signals.repostsReceived * 4;

  const engagementBonus =
    engagementTotal > 0
      ? Math.min(
          12,
          Math.log10(
            engagementTotal + 1
          ) * 5
        )
      : 0;

  row.followers =
    followers;

  row.following =
    following;

  row.signals =
    signals;

  const followerPower =
    followerSocialPower(
      followers
    );

  const followerBoost =
    followerDerivedSocialBoost(
      followerPower
    );

  row.followerPower =
    followerPower;

  row.popularity =
    clampPositiveSocial(
      followerPower +
      engagementBonus
    );

  /*
   * AURA / REPUTATION / HUMOR
   *
   * A karakter történeti/tartalmi core pontjai megmaradnak,
   * erre jön rá a követőszámból származó social leverage.
   */
  row.aura =
    clampSignedSocial(
      Number(
        row.auraCore
      ) +
      followerBoost.aura
    );

  row.reputation =
    clampSignedSocial(
      Number(
        row.reputationCore
      ) +
      followerBoost.reputation
    );

  row.humor =
    clampSignedSocial(
      Number(
        row.humorCore
      ) +
      followerBoost.humor
    );

  /*
   * HYPE:
   * friss esemény + követőszám alap-buzz + ideiglenes explicit +/-.
   */
  row.hype =
    clampPositiveSocial(
      recentHypeFor(
        w,
        characterId
      ) +
      followerBoost.hype +
      liveHypeModifier(
        row
      )
    );

  /*
   * CLOUT:
   * követőszám + a többi social pont.
   *
   * Minél magasabbak ezek a pontok, annál magasabb a clout.
   */
  row.clout =
    socialCloutScore(
      row,
      followerPower
    );

  row.sentiment =
    publicSentimentFor(
      w,
      characterId
    );

  const fanAudience = Math.max(0, row.followers);
  const stanShare = Math.min(0.28, (Number(row.sentiment.stanEnergy) || 0) / 420);
  const antiShare = Math.min(0.24, (Number(row.sentiment.cancelPressure) || 0) / 460);
  const skepticShare = Math.min(0.22, (Number(row.sentiment.controversy) || 0) / 520);
  const coreShare = Math.min(0.35, 0.04 + (Number(row.sentiment.support) || 0) / 430);
  row.fanbase = {
    coreFans: Math.round(fanAudience * coreShare),
    activeStans: Math.round(fanAudience * stanShare),
    skeptics: Math.round(fanAudience * skepticShare),
    antis: Math.round(fanAudience * antiShare),
  };

  row.viralPosts =
    (w.posts || []).filter(
      (p) =>
        p &&
        p.authorId ===
          characterId &&
        p.virality &&
        Number(
          p.virality.score
        ) >= 60
    ).length;

  row.updatedAt =
    now();

  return row;
}

function refreshAllSocialStats(w) {
  if (!w) return w;

  socialProfiles(w).forEach(
    (c) => {
      refreshSocialStatsFor(
        w,
        c.id
      );
    }
  );

  return w;
}

/*
 * Későbbi tartalmi rendszereknek:
 * gossip / cancel / stan / virality / popup event
 * adhat célzott társadalmi következményt.
 *
 * A jelenlegi like/comment/follow rendszer ezt NEM használja
 * reputation vagy aura automatikus farmolására.
 */
function applyExplicitSocialImpact(
  w,
  characterId,
  impact = {}
) {
  const row =
    ensureSocialStatsFor(
      w,
      characterId
    );

  if (!row) return null;

  if (
    Number.isFinite(
      Number(impact.aura)
    )
  ) {
    row.auraCore =
      clampSignedSocial(
        Number(
          row.auraCore
        ) +
        Number(
          impact.aura
        )
      );
  }

  if (
    Number.isFinite(
      Number(impact.reputation)
    )
  ) {
    row.reputationCore =
      clampSignedSocial(
        Number(
          row.reputationCore
        ) +
        Number(
          impact.reputation
        )
      );
  }

  if (
    Number.isFinite(
      Number(impact.humor)
    )
  ) {
    row.humorCore =
      clampSignedSocial(
        Number(
          row.humorCore
        ) +
        Number(
          impact.humor
        )
      );
  }

  if (
    Number.isFinite(
      Number(impact.hype)
    )
  ) {
    row.hypeModifier =
      clampSignedSocial(
        Number(
          row.hypeModifier
        ) +
        Number(
          impact.hype
        )
      );

    row.hypeModifierAt =
      now();
  }

  const profile =
    socialProfileById(
      w,
      characterId
    );

  if (
    profile &&
    Number.isFinite(
      Number(
        impact.followers
      )
    )
  ) {
    ensureSocialProfileRow(
      profile
    );

    profile.followerDelta =
      Math.round(
        Number(
          profile.followerDelta
        ) || 0
      ) +
      Math.round(
        Number(
          impact.followers
        )
      );
  }

  /*
   * A követőszám és a core pontok módosítása után
   * azonnal újraszámoljuk a derived statokat + cloutot.
   */
  const refreshed =
    refreshSocialStatsFor(
      w,
      characterId
    );

  if (refreshed) {
    return refreshed;
  }

  row.updatedAt =
    now();

  return row;
}

/*
 * =========================================================
 * SOCIAL EVENT LEDGER
 * =========================================================
 *
 * Minden fontos társadalmi történés egységes formában
 * kerül majd ide.
 *
 * Ebből dolgozhat később:
 * - Whisper Wire
 * - pletykarendszer
 * - virality
 * - hype
 * - reputation
 * - relationship következmények
 */

function socialScore(value, fallback = 0) {
  const n = Number(value);

  if (!Number.isFinite(n)) {
    return fallback;
  }

  return Math.max(
    0,
    Math.min(100, Math.round(n))
  );
}

function recordSocialEvent(
  w,
  event = {}
) {
  if (!w || typeof w !== "object") {
    return null;
  }

  ensureSocialSimulationState(w);

  const type =
    String(
      event.type || "event"
    ).trim() || "event";

  /*
   * Ha ugyanazt a konkrét posztot /
   * kommentet / eseményt egy retry miatt
   * még egyszer próbálnánk naplózni,
   * ne készüljön belőle duplikáció.
   */
  const refId =
    event.refId !== undefined &&
    event.refId !== null
      ? String(event.refId)
      : "";

  if (refId) {
    const existing =
      (w.socialEvents || []).find(
        (x) =>
          x &&
          x.type === type &&
          String(x.refId || "") ===
            refId
      );

    if (existing) {
      return existing;
    }
  }

  const rawTargets =
    Array.isArray(event.targetIds)
      ? event.targetIds
      : event.targetId
        ? [event.targetId]
        : [];

  const targetIds = [
    ...new Set(
      rawTargets
        .filter(Boolean)
        .map((x) => String(x))
    ),
  ];

  const rawWitnesses =
    Array.isArray(event.witnessIds)
      ? event.witnessIds
      : [];

  const witnessIds = [
    ...new Set(
      rawWitnesses
        .filter(Boolean)
        .map((x) => String(x))
    ),
  ];

  const allowedVisibility = [
    "public",
    "private",
    "group",
    "limited",
    "system",
  ];

  const visibility =
    allowedVisibility.includes(
      event.visibility
    )
      ? event.visibility
      : "public";

  const allowedFactLevels = [
    "observed",
    "inferred",
    "rumor",
    "speculation",
  ];

  const factLevel =
    allowedFactLevels.includes(
      event.factLevel
    )
      ? event.factLevel
      : "observed";

  const tags = Array.isArray(event.tags)
    ? [
        ...new Set(
          event.tags
            .map((x) =>
              String(x || "")
                .trim()
                .toLowerCase()
            )
            .filter(Boolean)
        ),
      ].slice(0, 12)
    : [];

  const entry = {
    id:
      event.id ||
      "se_" + uid(),

    refId,

    ts:
      Number(event.ts) ||
      now(),

    type,

    actorId:
      event.actorId
        ? String(event.actorId)
        : "",

    targetIds,

    witnessIds,

    visibility,

    factLevel,

    importance:
      socialScore(
        event.importance,
        20
      ),

    drama:
      socialScore(
        event.drama,
        0
      ),

    romance:
      socialScore(
        event.romance,
        0
      ),

    embarrassment:
      socialScore(
        event.embarrassment,
        0
      ),

    source:
      String(
        event.source || "world"
      ),

    text:
      String(
        event.text || ""
      ).trim(),

    tags,

    meta:
      event.meta &&
      typeof event.meta === "object" &&
      !Array.isArray(event.meta)
        ? {
            ...event.meta,
          }
        : {},
  };

  /*
   * A legújabb esemény legyen elöl.
   */
  w.socialEvents.unshift(entry);

  /*
   * Ne nőjön végtelenre a teljes world JSON.
   *
   * A nagyon régi fontos történeteket később
   * a Whisper Wire / history rendszer fogja
   * összefoglalva megőrizni.
   */
  w.socialEvents =
    w.socialEvents.slice(0, 600);

  /*
   * Csak az érintett profilokat frissítjük.
   * Így egy like/comment/repost azonnal megjelenik a
   * popularity/hype számításban, de nem fut végig fölöslegesen
   * az egész karaktergárdán.
   */
  const touchedIds = [
    entry.actorId,
    ...(entry.targetIds || []),
  ]
    .filter(Boolean);

  [
    ...new Set(
      touchedIds
    ),
  ].forEach((id) => {
    refreshSocialStatsFor(
      w,
      id
    );
  });

  /*
   * Későbbi rendszerek küldhetnek például:
   *
   * meta: {
   *   socialImpact: {
   *     reputation: -8,
   *     aura: 3
   *   }
   * }
   *
   * Ez most még csak infrastruktúra.
   */
  /*
   * Like / comment / reply / repost után azonnal újraszámoljuk
   * az érintett eredeti poszt terjedését.
   *
   * A "viral" eventet direkt kihagyjuk, így nincs rekurzív loop.
   */
  if (
    [
      "post",
      "like",
      "comment",
      "reply",
      "repost",
      "gossip-story",
      "rumor-evolution",
    ].includes(
      entry.type
    ) &&
    entry.meta &&
    entry.meta.postId
  ) {
    refreshPostVirality(
      w,
      entry.meta.postId
    );
  }

  if (
    entry.meta &&
    entry.meta.socialImpact &&
    typeof entry.meta.socialImpact ===
      "object"
  ) {
    const impactTargetIds =
      entry.targetIds &&
      entry.targetIds.length
        ? entry.targetIds
        : entry.actorId
          ? [entry.actorId]
          : [];

    impactTargetIds.forEach(
      (id) => {
        applyExplicitSocialImpact(
          w,
          id,
          entry.meta.socialImpact
        );
      }
    );
  }

  /*
   * A social ledger eseménye lehet egy backchannel rumor MAGJA.
   * Ez nem publikál semmit és nem teszi globálisan ismertté: csak azokat
   * a karaktereket fertőzi meg első kézből, akik ténylegesen látták /
   * átélték / megkapták az eseményt.
   */
  seedGossipPropagationFromEvent(w, entry);

  refreshTrends(w);

  if (entry.meta && entry.meta.postId) {
    refreshPostReach(w, entry.meta.postId);
  }

  /*
   * Aktív pletykamédiánál frissítjük a következő
   * valós alapú sztori-jelöltet.
   * EZ MÉG NEM PUBLIKÁL POSZTOT.
   */
  if (
    w.gossipSettings &&
    (
      w.gossipSettings.mediaMode === "local" ||
      w.gossipSettings.mediaMode === "global"
    )
  ) {
    selectGossipStoryCandidate(w);
  }

  return entry;
}

function mkAction(type, key, payload = {}, source = "auto") {
  return { id: uid(), type, key, payload, source, ts: now() };
}

function simEnqueue(w, action) {
  if (!action || !action.key) return false;
  const sim = ensureSimState(w);
  const doneAt = Number(sim.done[action.key] || 0);
  if (doneAt && now() - doneAt < SIM_DONE_TTL) return false;
  if (sim.queue.some((x) => x && x.key === action.key)) return false;
  if (action.source === "manual") {
    sim.queue.unshift(action);
    sim.queue = sim.queue.slice(0, SIM_QUEUE_LIMIT);
  } else {
    sim.queue.push(action);
    sim.queue = sim.queue.slice(-SIM_QUEUE_LIMIT);
  }
  sim.at = now();
  return true;
}

function simPeek(w) {
  const sim = ensureSimState(w);
  return sim.queue.length ? sim.queue[0] : null;
}

function simMarkRunning(w, action) {
  const sim = ensureSimState(w);
  sim.running = action && action.id ? action.id : "";
  sim.at = now();
}

function simDropQueued(w, actionId) {
  const sim = ensureSimState(w);
  sim.queue = sim.queue.filter((x) => x && x.id !== actionId);
  sim.at = now();
}

function simMarkDone(w, action) {
  const sim = ensureSimState(w);
  sim.running = "";
  if (action && action.key) sim.done[action.key] = now();
  sim.at = now();
}
/*
 * CHARACTER-DRIVEN GROUP ACTIVITY
 *
 * A beszédes/online aktív karakterek természetesen többet írhatnak,
 * a csendes/private karakterek ritkábban. Nincs mesterséges egyenlő kvóta.
 */
function fairGroupCast(w, allowedIds = null) {
  const cutoff = now() - 48 * 3600e3;

  const allowed = Array.isArray(allowedIds)
    ? new Set(allowedIds)
    : null;

  const chars = (w.chars || [])
    .filter(
      (c) =>
        c &&
        !isHuman(w, c.id) &&
        (!allowed || allowed.has(c.id))
    )
    .map((c) => {
      let recentGroupMessages = 0;
      let lastGroupMessageAt = 0;

      (w.groups || []).forEach((g) => {
        (g.msgs || []).forEach((m) => {
          if (!m || m.from !== c.id) return;
          const ts = Number(m.ts) || 0;
          if (ts >= cutoff) recentGroupMessages += 1;
          lastGroupMessageAt = Math.max(lastGroupMessageAt, ts);
        });
      });

      const activity = characterOnlineActivityProfile(w, c).group;
      const idleHours = lastGroupMessageAt
        ? Math.min(72, Math.max(0, (now() - lastGroupMessageAt) / 3600e3))
        : 72;

      const pressure =
        idleHours * (0.18 + activity * 0.55) +
        activity * 38 -
        recentGroupMessages * (6 / Math.max(0.30, activity * activity)) +
        Math.random() * 8;

      return {
        c,
        activity,
        recentGroupMessages,
        lastGroupMessageAt,
        pressure,
      };
    });

  chars.sort((a, b) =>
    (b.pressure - a.pressure) ||
    (b.activity - a.activity) ||
    (a.lastGroupMessageAt - b.lastGroupMessageAt)
  );

  return chars.map((x) => x.c);
}
async function genAutoGroup(w) {
  const cast = fairGroupCast(w, null).slice(0, 5);

  if (cast.length < 2) {
    return {
      skip: true,
      name: "",
      creator: "",
      members: [],
      messages: [],
      changes: [],
      event: "",
    };
  }

  const existingGroups = (w.groups || [])
    .slice(-8)
    .map((g) => {
      const names = (g.members || [])
        .map((id) => nameOfIn(w, id))
        .filter(Boolean)
        .join(", ");

      return `- ${g.name || "Névtelen csoport"}: ${names || "nincs tag"}`;
    })
    .join("\n");

  const recentPosts = (w.posts || [])
    .slice(0, 5)
    .map((p) => `${nameOfIn(w, p.authorId)}: ${p.text}`)
    .join("\n");

  return askWorldJSON(
    w,
    engineFor(w),
    `${worldContext(
      w,
      cast.map((c) => c.id),
      true,
      null
    )}

A VILÁG MOST MAGÁTÓL ÉL TOVÁBB.

Döntsd el, hogy a szereplők közül valakinek MOST természetes, karakterhű oka van-e új csoportos beszélgetést létrehozni.

LEHETSÉGES SZEREPLŐK:
${cast
  .map((c) => `${c.name} [${c.id}]`)
  .join("\n")}

A játékos:
${w.player.name} [${w.meId}]

FONTOS:
A játékos automatikusan résztvevője lesz a létrehozott group chatnek.
A játékos azonosítóját NE tedd bele a "members" listába.
A "members" listában kizárólag AI-karakterek legyenek.

MÁR LÉTEZŐ CSOPORTOK:
${existingGroups || "még nincs csoport"}

LEGUTÓBBI POSZTOK:
${recentPosts || "még nincs poszt"}

MOSTANI JEGYZETEK:
${notesForAI(w) || "nincs"}

LEGUTÓBBI VILÁGESEMÉNYEK:
${recentStructuredWorldLines(w, 8).join("\n") || "nincs"}

${cast
  .map((c) => `${voiceCard(c)}${characterMemoryCard(w, c)}`)
  .join("")}

${repetitionGuard(
  w,
  cast.map((c) => c.id),
  "autonóm csoportchat"
)}

${matureContentInstruction(
  w,
  cast.map((c) => c.id),
  "group"
)}

ÚJ GROUP CHAT SZABÁLYOK:

- NE hozz létre csoportot csak azért, mert technikailag lehet.
- Csak akkor legyen új group chat, ha legalább két AI-karakternek tényleges, jelenlegi és karakterhű oka van rá.
- Az ok következzen a kapcsolatokból, friss eseményekből, posztokból, kommentekből, jegyzetekből, pletykákból, konfliktusokból, tervekből vagy közös ügyekből.
- Az ok lehet teljesen hétköznapi is; nem kell minden új csoport mögé nagy dráma.
- Lehet például buli szervezése, program, pletyka, közös terv, probléma, konfliktus, segítségkérés, meghívás, titkos egyeztetés, közös ügy, közös érdeklődés vagy spontán társas beszélgetés.
- Ne találj ki mesterséges eseményt csak azért, hogy legyen oka a csoportnak.
- Ne hozz létre új csoportot, ha egy már létező group chat lényegében ugyanazokra az emberekre és ugyanarra a témára szolgál.
- Ne készíts újra és újra ugyanolyan összetételű csoportokat.
- Ne legyen minden társas interakcióból új group chat.
- 2-4 AI-karakter legyen a csoportban.
- A "creator" annak a karakternek az azonosítója legyen, aki természetesen létrehozná a csoportot.
- A creator mindig szerepeljen a "members" listában.
- Csak olyan karakter kerüljön be, akit a creator ténylegesen hozzáadna.
- A tagok kapcsolatai is számítsanak: ne rakj össze egymással teljesen irreleváns embereket pusztán a változatosság kedvéért.
- A játékos automatikusan résztvevője lehet a rendszer szerint, de a játékos ne kerüljön az AI "members" listájába, és helyette SOHA ne írj üzenetet.

CSOPORTNÉV:

- Legyen természetes, mintha valódi emberek nevezték volna el.
- A név tükrözheti azt is, KI hozta létre a csoportot.
- Nem kell hivatalosnak vagy szépen megfogalmazottnak lennie.
- Lehet nagyon rövid.
- Lehet vicces.
- Lehet belsős poén.
- Lehet eseménynév.
- Lehet helynév.
- Lehet konkrét tervre utaló név.
- Lehet szándékosan hülye vagy kaotikus, ha a creator ilyen.
- Lehet kisbetűs vagy furcsán központozott, ha ez illik hozzájuk.
- Ritkán emoji is lehet a csoportnévben, ha a creator természetesen így nevezné el.
- Ne legyen minden név generikus, például "Barátok", "Group", "Beszélgetés" vagy "Csapat".
- Ne próbálj minden névből kreatív szóviccet csinálni.
- Egy praktikus, egyszerű név is teljesen természetes lehet.

KEZDŐ ÜZENETEK:

- Adj 2-5 rövid kezdő üzenetet.
- Legalább két különböző AI-tag szólaljon meg a nyitó beszélgetésben.
- Nem kell minden tagnak megszólalnia.
- Ugyanaz a karakter küldhet két egymást követő rövid üzenetet is, ha ez természetes chatritmus.
- Ezek VALÓDI group chat üzenetek, NEM roleplay-jelenetek.
- Úgy hassanak, mintha a tagok ténylegesen telefonról írnának a most létrehozott csoportba.
- A legtöbb üzenet legyen rövid.
- Egyetlen szó is lehet teljes üzenet.
- Egy 1-3 szavas reakció teljesen természetes.
- Lehet félmondat.
- Lehet kérdés.
- Lehet beszólás.
- Lehet poén.
- Lehet pletyka.
- Lehet flört.
- Lehet vita.
- Lehet provokáció.
- Lehet szervezés.
- Lehet száraz reakció.
- Lehet csak egy név vagy @megszólítás.
- Ne próbálj minden üzenetből teljes, szépen lezárt mondatot készíteni.
- Ne írjanak hosszú bekezdéseket.
- Ne írjanak monológokat.
- Ne írjanak regényszerű, költői vagy irodalmi szöveget.
- Ne narráljanak jelenetet.
- Ne írjanak belső gondolatokat.
- Ne használjanak *csillagok közé tett cselekvéseket*.
- Ne magyarázzák el a kapcsolatukat egymással.
- Ne írják le, hogyan néznek, mosolyognak, sóhajtanak vagy mit csinálnak fizikailag.
- Csak azt írják, amit ténylegesen elküldenének a group chatbe.

VALÓDI GROUP CHAT DINAMIKA:

- A karakterek reagáljanak egymás KONKRÉT üzeneteire.
- Ne úgy nézzen ki, mintha mindenki külön válaszolna ugyanarra a láthatatlan kérdésre.
- Egy karakter kijavíthatja a másikat.
- Rávághat valamire.
- Rálicitálhat egy poénra.
- Beszólhat.
- Visszakérdezhet.
- Félbeszakíthatja a témát egy rövid reakcióval.
- @néven megszólíthat valakit.
- Két karakter röviden egymásnak is eshet.
- Valaki reagálhat csak arra, amit az előző tag mondott.
- Nem kell minden üzenetnek új információt tartalmaznia.
- Egy "mi van??", "ne.", "te hülye", "????" jellegű SZERKEZET lehet természetes, de ezeket ne másold sablonként.
- A beszélgetés lehet kissé kaotikus; nem kell tökéletesen rendezettnek lennie.

KARAKTERHŰ ONLINE STÍLUS:

- Minden tag a SAJÁT kommunikációs stílusában írjon.
- Használhatnak kisbetűt, NAGYBETŰT, szlenget, rövidítéseket, internetes nyelvet, elnyújtott szavakat, több kérdőjelet vagy felkiáltójelet, ha ez illik hozzájuk.
- Nem kell mindenkinek ugyanolyan helyesen és rendezett mondatokban írnia.
- Egy szűkszavú karakter maradjon szűkszavú.
- Egy kaotikus karakter lehessen kaotikus.
- Egy száraz karakter írhat minimálisan.
- Egy flörtölős karakter lehet direkt.
- Egy domináns karakter könnyen átveheti a beszélgetés ritmusát.
- Egy visszahúzódó karakter nem köteles mindenre reagálni.
- Már a megfogalmazásból érződjön, KI írta az adott üzenetet.

EMOJI:

- Az emoji-használat legyen ténylegesen jelen a group chatben, HA a résztvevő karakterek között van olyan, aki természetesen használ emojit.
- Ha van ilyen karakter, a 2-5 kezdő üzenet között legalább egy tartalmazzon emojit.
- Általában 1-2 emoji elég egy üzenetben.
- Néha egyetlen emoji is lehet teljes reakció.
- Az emoji lehet a szöveg elején, közepén vagy végén.
- Nem kell mindenkinek emojit használnia.
- Ne kényszeríts emojit olyan karakterre, akinek ez nem illik a stílusához.
- Ritkán több emoji is természetes lehet egy kifejezetten expresszív karakternél.
- Ne használják folyton ugyanazokat.
- Ne legyen minden flört ❤️ vagy 😏.
- Ne legyen minden nevetés 😂 vagy 😭.
- Az emoji típusa igazodjon ahhoz, KI ír, kinek reagál és mi történik éppen.

ISMÉTLÉSVÉDELEM:

- Ne ismételjék korábbi group chat üzeneteiket.
- Ne parafrazálják újra ugyanazt.
- Ne ismételjék ugyanazokat a poénokat.
- Ne ismételjék ugyanazokat a sértéseket.
- Ne ismételjék ugyanazokat a fenyegetéseket.
- Ne ismételjék ugyanazokat a flörtölési formulákat.
- Ne ragadjanak bele ugyanazokba a becenevekbe.
- Ne használják mindig ugyanazokat az emoji-kombinációkat.
- Ne induljon minden új group chat ugyanolyan mondattal.
- A példamondatok és hangminták CSAK stílusiránymutatások.
- SOHA ne másold őket.
- SOHA ne készíts belőlük közeli parafrázist.
- A példákból a karakter ritmusát, szóhasználatát, humorát, közvetlenségét és kommunikációs szokásait tanuld meg.
- Minden konkrét üzenet legyen friss.

LEGFONTOSABB:

A csoport és az első néhány üzenet első pillantásra úgy hasson, mint egy valódi baráti, ellenséges, pletykálkodó vagy praktikus group chat indulása. Ha inkább hangzik előre megírt jelenetnek, regénydialógusnak vagy több AI-karakter egymás mellé rakott mini monológjának, ÍRD ÚJRA rövidebbre, közvetlenebbre és egymásra reagálóbbra.

Ha nincs most valódi oka új csoport létrehozásának:
"skip": true

Ha van:
"skip": false

Formátum:
{"skip":false,
"name":"a csoport neve",
"creator":"a létrehozó karakter azonosítója",
"members":["karakter id","karakter id"],
"messages":[
  {"id":"karakter azonosítója","text":"rövid group chat üzenet"},
  {"id":"karakter azonosítója","text":"rövid válasz"}
],
"changes":[
  {"a":"aki érez","b":"aki iránt","delta":5,"mood":"mit érez most iránta","why":"egy rövid mondat"}
],
"selfUpdates":[{"id":"AI id","mood":"mi dolgozik benne","intent":"mit akar most","openLoops":["nyitott terv vagy ügy"]}],
"relationshipUpdates":[
  {"id":"AI id","targetId":"a másik konkrét karakter id-ja","currentFeeling":"csak az adott ember felé MOST élő érzés vagy üres","currentIntent":"mit akar vele kapcsolatban következőnek vagy üres","lastTone":"az interakció tényleges hangneme röviden vagy üres","perceivedTargetMood":"amit az AI a látható jelekből a másik hangulatáról HISZ; lehet téves vagy üres","addOpenLoops":["új, ténylegesen félbemaradt kérdés/ügy"],"resolveOpenLoops":["az a korábbi nyitott ügy, ami MOST ténylegesen lezárult"],"addPromises":["csak explicit ígéret/vállalás"],"resolvePromises":["most teljesült/visszavont ígéret"],"addPlans":["konkrét közös jövőbeli terv"],"resolvePlans":["most teljesült/lemondott terv"]}
],
"event":"egy rövid mondat arról, miért jött létre a csoport"}${TAIL}`,
    { maxTokens: 1200, priority: 18 }
  );
}


async function genSocialWave(
  w,
  target,
  post,
  mode,
  castRows
) {
  const cast =
    (castRows || [])
      .map(
        (row) =>
          charById(
            w,
            row.id
          )
      )
      .filter(Boolean);

  if (
    !target ||
    !cast.length
  ) {
    return {
      comments: [],
    };
  }

  const castIds =
    cast.map(
      (c) => c.id
    );

  const modeText =
    mode === "cancel"
      ? `
NYILVÁNOS BACKLASH / CANCEL HULLÁM:
A felsorolt karakterek közül azok szólaljanak meg,
akik a saját személyiségük és ${target.name}-hez fűződő
kapcsolatuk alapján tényleg kritikusan, ellenségesen,
szkeptikusan vagy gúnyosan reagálnának.
`
      : mode === "counter"
        ? `
COUNTER-BACKLASH:
${target.name} támadások alatt áll, de kialakult egy
védőtábor is. A felsorolt karakterek közül azok
szólaljanak meg, akik természetesen megvédenék,
visszaszólnának a támadóknak vagy nyilvánosan mellé állnának.
`
        : `
STAN / SUPPORT HULLÁM:
${target.name} körül erős támogatói energia alakult ki.
A felsorolt karakterek közül azok reagáljanak, akik
természetesen támogatnák, hype-olnák vagy megvédenék.
`;

  return askWorldJSON(
    w,
    engineFor(w),
    `${worldContext(
      w,
      castIds.concat(
        [target.id]
      ),
      true,
      null
    )}

SOCIAL MEDIA HULLÁM.

CÉLPONT:
${target.name} [${target.id}]

${post
  ? `A POSZT, AMI KÖRÜL A HULLÁM FUT:
${target.name}: ${post.text || "[képes poszt]"}`
  : "Nincs egyetlen konkrét poszt; a hullám a profil körül zajlik."}

${modeText}

MEGSZÓLALHATÓ KARAKTEREK:
${cast
  .map(
    (c) =>
      `${c.name} [${c.id}]
${voiceCard(c)}
${characterMemoryCard(w, c)}`
  )
  .join("\n\n")}

${repetitionGuard(
  w,
  castIds,
  "kommentek"
)}

SZABÁLYOK:
- CSAK a fenti AI-karakterek nevében írj.
- A játékos helyett SOHA ne írj.
- Ne szólaljon meg mindenki kötelezően.
- 1-3 rövid, valódi social-media komment legyen.
- Legtöbbször 1-15 szó bőven elég.
- Ne írj esszét vagy narrációt.
- A hangnem legyen karakterhű.
- Ne használj ugyanazt a mondatot vagy emoji-mintát több szereplőnél.
- Ne találj ki olyan titkos információt, amit a karakter nem tudhat.
- ${mode === "cancel"
  ? "A kritika lehet kemény vagy gúnyos, de ne legyen mindenki ugyanúgy dühös."
  : "A támogatás lehet védelem, hype, száraz beszólás az ellenzőknek vagy egyszerű kiállás."}

Formátum:
{
  "comments":[
    {
      "id":"karakter azonosítója",
      "text":"rövid nyilvános komment"
    }
  ]
}${TAIL}`,
    {
      maxTokens: 900,
    }
  );
}

function applySocialWave(
  n,
  action,
  out
) {
  const payload =
    action &&
    action.payload
      ? action.payload
      : {};

  const targetId =
    payload.targetId;

  const mode =
    payload.mode ||
    "stan";

  const target =
    socialProfileById(
      n,
      targetId
    );

  if (!target) {
    return;
  }

  const row =
    ensureSocialStatsFor(
      n,
      targetId
    );

  const sentiment =
    row &&
    row.sentiment
      ? row.sentiment
      : defaultSocialStatsRow()
          .sentiment;

  const post =
    payload.postId
      ? (n.posts || []).find(
          (p) =>
            p &&
            p.id ===
              payload.postId
        )
      : strongestSocialPostFor(
          n,
          targetId
        );

  const cast =
    Array.isArray(
      payload.cast
    )
      ? payload.cast
      : [];

  /*
   * A konkrét létező AI-k is viselkednek:
   * supportnál follow / like / repost,
   * cancelnél unfollow.
   */
  cast.forEach((castRow) => {
    const who =
      castRow &&
      castRow.id;

    const actor =
      socialProfileById(
        n,
        who
      );

    if (
      !actor ||
      isHuman(n, actor.id) ||
      actor.id === targetId
    ) {
      return;
    }

    if (
      mode === "cancel"
    ) {
      const rel =
        getRel(
          n,
          actor.id,
          targetId
        );

      const relScore =
        Number(
          rel && rel.score
        ) || 0;

      if (
        isFollowing(
          n,
          actor.id,
          targetId
        ) &&
        relScore < 15
      ) {
        setFollowState(
          n,
          actor.id,
          targetId,
          false,
          "ai-social-wave"
        );
      }

      return;
    }

    /*
     * Stan / counter:
     * a védők érdeklődése láthatóvá válhat.
     */
    if (
      !isFollowing(
        n,
        actor.id,
        targetId
      ) &&
      socialSupportScore(
        n,
        actor.id,
        targetId
      ) >= 28
    ) {
      setFollowState(
        n,
        actor.id,
        targetId,
        true,
        "ai-social-wave"
      );
    }

    if (post) {
      if (
        !Array.isArray(
          post.likedBy
        )
      ) {
        post.likedBy = [];
      }

      if (
        !post.likedBy.includes(
          actor.id
        )
      ) {
        post.likedBy.push(
          actor.id
        );

        post.likes =
          Math.max(
            Number(
              post.likes
            ) || 0,
            post.likedBy.length
          );

        recordSocialEvent(
          n,
          {
            type: "like",
            refId:
              `${post.id}:${actor.id}`,
            ts: now(),
            actorId:
              actor.id,
            targetIds:
              post.authorId !==
                actor.id
                ? [
                    post.authorId,
                  ]
                : [],
            visibility:
              "public",
            factLevel:
              "observed",
            importance: 8,
            drama: 0,
            romance: 0,
            embarrassment: 0,
            source:
              "ai-social-wave",
            text:
              "Liked a post.",
            tags: [
              "social",
              "like",
              "stan",
              "support-wave",
            ],
            meta: {
              postId:
                post.id,
              postAuthorId:
                post.authorId ||
                "",
            },
          }
        );
      }

      if (
        socialSupportScore(
          n,
          actor.id,
          targetId
        ) >= 50 &&
        !hasReposted(
          n,
          actor.id,
          post.id
        )
      ) {
        createRepost(
          n,
          actor.id,
          post.id,
          "ai-social-wave"
        );
      }
    }
  });

  /*
   * AI által írt nyilvános kommentek.
   */
  if (post) {
    (out &&
    Array.isArray(out.comments)
      ? out.comments
      : []
    ).slice(0, 3).forEach(
      (comment) => {
        const who =
          aiVoice(
            n,
            comment &&
            comment.id
          );

        if (
          !who ||
          !cast.some(
            (row) =>
              row &&
              row.id === who
          ) ||
          !comment.text
        ) {
          return;
        }

        if (!isHuman(n, who) && who === post.authorId) return;

        let body =
          cleanGeneratedComment(
            n,
            who,
            comment.text,
            240
          );

        if (!body) return;
        body = sanitizeGeneratedDirectAddress(n, who, post.authorId, body);
        if (!body) return;

        const made = {
          id: uid(),
          authorId: who,
          text: body,
          ts: now(),
          parent: null,
          language:
            worldLanguage(
              n,
              n.meId
            ),
        };

        post.comments = safePostComments(post);

        post.comments.push(
          made
        );

        noteComment(
          n,
          post,
          made
        );

        recordSocialEvent(
          n,
          {
            type: "comment",
            refId:
              made.id,
            ts:
              made.ts,
            actorId:
              who,
            targetIds: [
              targetId,
            ],
            visibility:
              "public",
            factLevel:
              "observed",
            importance:
              mode === "cancel"
                ? 34
                : 28,
            drama:
              mode === "cancel"
                ? 28
                : mode ===
                    "counter"
                  ? 20
                  : 10,
            romance: 0,
            embarrassment: 0,
            source:
              "ai-social-wave",
            text:
              made.text,
            tags:
              mode === "cancel"
                ? [
                    "social",
                    "comment",
                    "cancel",
                    "backlash",
                    "controversy",
                  ]
                : mode ===
                    "counter"
                  ? [
                      "social",
                      "comment",
                      "stan",
                      "support-wave",
                      "counter-backlash",
                      "controversy",
                    ]
                  : [
                      "social",
                      "comment",
                      "stan",
                      "support-wave",
                    ],
            meta: {
              postId:
                post.id,
              commentId:
                made.id,
              postAuthorId:
                targetId,
            },
          }
        );
      }
    );
  }

  const strength =
    mode === "cancel"
      ? Number(
          sentiment.cancelPressure
        ) || 0
      : mode === "counter"
        ? Math.max(
            Number(
              sentiment.cancelPressure
            ) || 0,
            Number(
              sentiment.stanEnergy
            ) || 0
          )
        : Number(
            sentiment.stanEnergy
          ) || 0;

  const followerDelta =
    waveBackgroundFollowerDelta(
      n,
      targetId,
      mode,
      strength
    );

  ensureSocialProfileRow(
    target
  );

  target.followerDelta =
    Math.round(
      Number(
        target.followerDelta
      ) || 0
    ) +
    followerDelta;

  const reputationDelta =
    mode === "cancel"
      ? -Math.max(
          2,
          Math.min(
            10,
            Math.round(
              strength / 10
            )
          )
        )
      : mode === "counter"
        ? Math.max(
            1,
            Math.min(
              5,
              Math.round(
                strength / 20
              )
            )
          )
        : 0;

  recordSocialEvent(
    n,
    {
      type:
        mode === "cancel"
          ? "cancel-wave"
          : "stan-wave",

      refId:
        `social-wave:${mode}:${targetId}:${Math.floor(
          now() /
          21600000
        )}`,

      ts: now(),

      actorId: "",

      targetIds: [
        targetId,
      ],

      visibility:
        "public",

      factLevel:
        "observed",

      importance:
        mode === "cancel"
          ? 78
          : mode ===
              "counter"
            ? 70
            : 58,

      drama:
        mode === "cancel"
          ? 72
          : mode ===
              "counter"
            ? 55
            : 25,

      romance: 0,
      embarrassment:
        mode === "cancel"
          ? 25
          : 0,

      source:
        "social-engine",

      text:
        mode === "cancel"
          ? "A public backlash wave formed."
          : mode === "counter"
            ? "A counter-backlash formed around the target."
            : "A visible support wave formed.",

      tags:
        mode === "cancel"
          ? [
              "social",
              "social-wave",
              "cancel",
              "backlash",
              "controversy",
            ]
          : mode === "counter"
            ? [
                "social",
                "social-wave",
                "counter",
                "stan",
                "support-wave",
                "counter-backlash",
                "controversy",
              ]
            : [
                "social",
                "social-wave",
                "stan",
                "support-wave",
              ],

      meta: {
        mode,
        followerDelta,

        publicSentiment:
          mode === "cancel"
            ? {
                dislike: 18,
                controversy: 15,
                cancel: 18,
              }
            : mode ===
                "counter"
              ? {
                  support: 16,
                  controversy: 10,
                  stan: 14,
                }
              : {
                  support: 14,
                  stan: 16,
                },

        socialImpact: {
          hype:
            mode === "cancel"
              ? 12
              : mode ===
                  "counter"
                ? 9
                : 6,

          reputation:
            reputationDelta,
        },
      },
    }
  );

  refreshSocialStatsFor(
    n,
    targetId
  );

  if (
    isHuman(
      n,
      targetId
    )
  ) {
    const absFollowers =
      Math.abs(
        followerDelta
      );

    pushNote(
      n,
      targetId,
      {
        icon:
          mode === "cancel"
            ? "⚠"
            : mode ===
                "counter"
              ? "🛡️"
              : "★",

        text:
          mode === "cancel"
            ? sysLangText(
                n,
                targetId,
                `Backlash indult körülötted. ${absFollowers} követőt veszítettél.`,
                `A backlash wave formed around you. You lost ${absFollowers} followers.`
              )
            : mode === "counter"
              ? sysLangText(
                  n,
                  targetId,
                  `A védőtáborod visszavágott. +${absFollowers} követő`,
                  `Your supporters pushed back. +${absFollowers} followers`
                )
              : sysLangText(
                  n,
                  targetId,
                  `Támogatói hullám indult körülötted. +${absFollowers} követő`,
                  `A support wave formed around you. +${absFollowers} followers`
                ),

        link:
          post
            ? {
                type: "post",
                id: post.id,
              }
            : {
                type: "char",
                id: targetId,
              },
      }
    );
  }
}

function lastAiFeedPostAt(w) {
  return (w && Array.isArray(w.posts) ? w.posts : [])
    .filter(
      (p) =>
        p &&
        p.authorId &&
        !isHuman(w, p.authorId)
    )
    .reduce(
      (latest, p) =>
        Math.max(
          latest,
          Number(p.ts) || 0
        ),
      0
    );
}

function feedNeedsFreshPost(w) {
  const last = lastAiFeedPostAt(w);

  /*
   * LIVING WORLD v51 — POST IS THE PRIMARY PULSE.
   * A világ leggyakoribb önálló tartalmi mozdulata az új poszt. A karakter-
   * aktivitás továbbra is számít, de a feed nem vár perceket DM/reply mögött.
   */
  const postPeak = Math.max(0.55, channelActivityPeak(w, "post"));
  const target = Math.max(25000, Math.round(LIVE_WORLD_POST_TARGET_MS / Math.min(1.85, postPeak)));
  return !last || now() - last >= target;
}

function freshFeedPostCommentCandidate(w) {
  if (!w) return null;
  const ts = now();

  const ranked = (w.posts || [])
    .filter((post) => {
      if (!post || !post.id || !post.authorId) return false;
      const age = ts - (Number(post.ts) || 0);
      if (age < 9000 || age > LIVE_WORLD_FRESH_COMMENT_WINDOW_MS) return false;

      const comments = safePostComments(post);
      if (comments.length >= LIVE_WORLD_FRESH_COMMENT_MAX) return false;
      if (Number(post.autoCommentedAt) > 0) return false;

      const lastCommentAt = comments.reduce(
        (latest, c) => Math.max(latest, Number(c && c.ts) || 0),
        0
      );
      if (lastCommentAt && ts - lastCommentAt < LIVE_WORLD_FRESH_COMMENT_GAP_MS) return false;
      return true;
    })
    .map((post) => {
      const age = Math.max(0, ts - (Number(post.ts) || 0));
      const comments = safePostComments(post);
      const ageRatio = Math.min(1, age / LIVE_WORLD_FRESH_COMMENT_WINDOW_MS);
      const freshness = (1 - ageRatio) * 100;
      const underCommented = Math.max(0, LIVE_WORLD_FRESH_COMMENT_MAX - comments.length) * 9;
      const authorIsPlayer = isHuman(w, post.authorId) ? 18 : 0;
      const juicy = publicSocialJuiceSignals(post.text || post.imageDescription || "").juicy ? 10 : 0;
      return {
        post,
        score: freshness + underCommented + authorIsPlayer + juicy + Math.random() * 8,
      };
    })
    .sort((a, b) => b.score - a.score);

  return ranked.length ? ranked[0].post : null;
}

function lastAiInitiatedRoleplayAt(w) {
  return (w && Array.isArray(w.scenes) ? w.scenes : []).reduce(
    (latest, scene) => scene && scene.aiInitiated
      ? Math.max(latest, Number(scene.startedAt || scene.ts) || 0)
      : latest,
    0
  );
}

function canAiInitiateRoleplay(w) {
  if (!w || !(w.chars || []).length) return false;
  const ts = now();
  /* A stale, régen megnyitva maradt AI-Event nem némíthatja el örökre az
     új meghívásokat. Csak egy TÉNYLEG friss, még aktív kezdeményezés blokkol. */
  const recentOpenAiScenes = (w.scenes || []).filter((scene) => {
    if (!scene || !scene.open || !scene.aiInitiated) return false;
    const started = Number(scene.startedAt || scene.ts) || 0;
    if (!started) return false;
    const latestTurnAt = (scene.turns || []).reduce(
      (latest, turn) => Math.max(latest, Number(turn && turn.ts) || 0),
      0
    );
    const lastActivityAt = Math.max(started, latestTurnAt);
    const idleAge = ts - lastActivityAt;
    const hasPlayerTurns = (scene.turns || []).some((turn) => turn && turn.authorId === w.meId);
    const accepted = ["accepted", "accepted_in_chat"].includes(String(scene.invitationStatus || "")) || hasPlayerTurns;
    /* Only a genuinely active Event suppresses a new invitation. A forgotten
       open scene may remain in the UI without muting this lane for 18 minutes. */
    return accepted ? idleAge < 7 * 60 * 1000 : idleAge < 2 * 60 * 1000;
  }).length;
  if (recentOpenAiScenes >= 1) return false;

  const simLast = Number(w.sim && w.sim.lastRoleplayInviteAt) || 0;
  const historyLast = lastAiInitiatedRoleplayAt(w);
  const last = Math.max(simLast, historyLast);
  const rpPeak = Math.max(0.55, channelActivityPeak(w, "roleplay"));
  const target = Math.max(2 * 60 * 1000, Math.round(LIVE_WORLD_EVENT_TARGET_MS / Math.min(1.75, rpPeak)));
  return !last || ts - last >= target;
}

function roleplayInitiationProbeDue(w) {
  const attemptAt = Number(w && w.sim && w.sim.roleplayAttemptAt) || 0;
  return !attemptAt || now() - attemptAt >= 35 * 1000;
}

function roleplayInitiatorScore(w, c) {
  if (!w || !c || isHuman(w, c.id)) return -999;
  let score = 12 + socialInteractionInterest(w, c.id, w.meId) * 0.42;
  const rel = getRel(w, c.id, w.meId);
  const lore = [c.personality,c.traits,c.goals,c.backstory,c.extra,rel && rel.mood,rel && rel.hidden,rel && rel.bond]
    .filter(Boolean).join(" ").toLowerCase();
  score += Math.min(26, Math.abs(Number(rel && rel.score) || 0) * 0.22);
  score += relationshipObsessionLevel(w, c.id, w.meId) * 16;
  score += (characterOnlineActivityProfile(w, c).roleplay - 1) * 24;
  if (/party|buli|social|társas|outgoing|extrovert|impulsive|impulzív|adventure|kaland|flirt|flört/.test(lore)) score += 14;
  if (/jealous|féltéken|possess|birtokl|obsess|megszáll|dominant|domináns|psycho|pszichopat|unhinged|kiszámíthatatlan/.test(lore)) score += 10;
  const mem = ensureCharMemory(w, c.id);
  if (mem.selfState && mem.selfState.intent) score += 8;
  return score + Math.random() * 18;
}

function pickRoleplayInitiator(w) {
  const pool = (w.chars || [])
    .filter((c) => c && !isHuman(w, c.id))
    .map((c) => ({ c, score: roleplayInitiatorScore(w, c) }))
    .sort((a,b) => b.score - a.score);

  const eligible = pool.filter((row) => row.score >= 14).slice(0, 4);
  return eligible.length
    ? eligible[Math.floor(Math.random() * eligible.length)].c
    : null;
}


function roleplayBirthYear(c) {
  const raw = String((c && c.birth) || "");
  const m = raw.match(/\b(19\d{2}|20\d{2})\b/);
  return m ? Number(m[1]) : 0;
}

function roleplayAffiliationTags(c) {
  if (!c) return [];
  const text = [
    c.job,
    c.bio,
    c.backstory,
    c.extra,
    c.goals,
  ].filter(Boolean).join(" ").toLowerCase();

  const defs = [
    ["cobra-kai", /cobra\s*kai/],
    ["iron-dragons", /iron\s*dragons?/],
    ["miyagi-do", /miyagi[\s-]*do/],
    ["miyagi-fang", /miyagi[\s-]*fang/],
    ["eagle-fang", /eagle\s*fang/],
    ["la-mamba", /la\s*mamba/],
    ["borderland", /borderland|borderline\s*games?/],
  ];

  return defs
    .filter(([, re]) => re.test(text))
    .map(([tag]) => tag);
}

function roleplayInviteeRoster(w, host) {
  if (!w || !host) return "-";
  const hostTags = new Set(roleplayAffiliationTags(host));
  const hostYear = roleplayBirthYear(host);

  return (w.chars || [])
    .filter((c) => c && c.id !== host.id && !isHuman(w, c.id))
    .map((c) => {
      const rel = getRel(w, host.id, c.id);
      const tags = roleplayAffiliationTags(c);
      const shared = tags.filter((tag) => hostTags.has(tag));
      const year = roleplayBirthYear(c);
      const ownStudent = isOwnSenseiRelationship(w, c.id, host.id);
      const hostOwnSensei = isOwnSenseiRelationship(w, host.id, c.id);
      return {
        c,
        rel,
        year,
        shared,
        ownStudent,
        hostOwnSensei,
        sensei: characterIsSensei(c),
        proximity:
          Math.abs(Number(rel && rel.score) || 0) +
          (ownStudent || hostOwnSensei ? 70 : 0) +
          shared.length * 30 +
          (hostYear && year ? Math.max(0, 18 - Math.abs(hostYear - year) * 2) : 0),
      };
    })
    .sort((a, b) => b.proximity - a.proximity)
    .slice(0, 40)
    .map((row) => {
      const bits = [
        `${row.c.name} [${row.c.id}]`,
        row.c.birth ? `birth=${cut(String(row.c.birth), 36)}` : "",
        row.c.job ? `role=${cut(String(row.c.job), 70)}` : "",
        row.shared.length ? `shared=${row.shared.join(",")}` : "",
        row.ownStudent ? "THIS PERSON IS YOUR OWN STUDENT" : "",
        row.hostOwnSensei ? "THIS PERSON IS YOUR OWN SENSEI/TEACHER" : "",
        row.sensei ? "sensei=true" : "",
        row.rel && row.rel.bond ? `bond=${cut(String(row.rel.bond), 36)}` : "",
        Number(row.rel && row.rel.score) ? `rel=${Number(row.rel.score)}` : "",
      ].filter(Boolean);
      return `- ${bits.join(" | ")}`;
    })
    .join("\n") || "-";
}

function roleplayEventAudienceScore(w, host, candidate, descriptor, explicit = false) {
  if (!w || !host || !candidate || candidate.id === host.id || isHuman(w, candidate.id)) return -999;

  const eventText = String(descriptor || "").toLowerCase();
  const candidateText = [
    candidate.job,
    candidate.bio,
    candidate.backstory,
    candidate.extra,
    candidate.goals,
    candidate.personality,
    candidate.traits,
  ].filter(Boolean).join(" ").toLowerCase();

  const hostTags = new Set(roleplayAffiliationTags(host));
  const candTags = roleplayAffiliationTags(candidate);
  const sharedTags = candTags.filter((tag) => hostTags.has(tag));
  const eventTags = roleplayAffiliationTags({ job: eventText });
  const rel = getRel(w, host.id, candidate.id);
  const reverse = getRel(w, candidate.id, host.id);
  const relScore = Number(rel && rel.score) || 0;
  const reverseScore = Number(reverse && reverse.score) || 0;
  const ownStudent = isOwnSenseiRelationship(w, candidate.id, host.id);
  const hostOwnSensei = isOwnSenseiRelationship(w, host.id, candidate.id);
  const candidateSensei = characterIsSensei(candidate);
  const hostYear = roleplayBirthYear(host);
  const candYear = roleplayBirthYear(candidate);
  const yearDiff = hostYear && candYear ? Math.abs(hostYear - candYear) : 99;

  const isTraining = /\b(?:practice|training|train|dojo|karate|lesson|class|sparring|edz[eé]s|gyakorl[aá]s|karate|dojo|sparring)\b/.test(eventText);
  const isParty = /\b(?:party|buli|cabin|house\s*party|bonfire|club\s*night|afterparty|h[aá]zibuli|kabinos?\s*buli)\b/.test(eventText);
  const isTeam = /\b(?:meeting|briefing|mission|team|crew|squad|practice|training|munka|megbesz[eé]l[eé]s|küldet[eé]s|csapat)\b/.test(eventText);

  let score = explicit ? 120 : 0;
  score += Math.max(-18, Math.min(28, relScore * 0.22));
  score += Math.max(-10, Math.min(16, reverseScore * 0.10));
  if (rel && /friend|bar[aá]t|close|best|ally|sz[oö]vets[eé]ges|partner/.test(String(rel.bond || "").toLowerCase())) score += 24;
  if (sharedTags.length) score += 18 + sharedTags.length * 12;
  if (eventTags.some((tag) => candTags.includes(tag))) score += 34;

  if (isTraining) {
    if (ownStudent) score += 95;
    if (hostOwnSensei) score += 55;
    if (candidateSensei && (sharedTags.length || eventTags.some((tag) => candTags.includes(tag)))) score += 52;
    if (/student|di[aá]k|karate|fighter|harcos|sensei|coach|edz[oő]|instructor/.test(candidateText)) score += 18;
    if (!ownStudent && !hostOwnSensei && !sharedTags.length && !eventTags.some((tag) => candTags.includes(tag))) score -= 32;
  }

  if (isParty) {
    if (yearDiff <= 4) score += 30;
    else if (yearDiff <= 8) score += 20;
    else if (yearDiff <= 12) score += 8;
    if (candYear && new Date().getFullYear() - candYear <= 35) score += 10;
    score += Math.round((characterOnlineActivityProfile(w, candidate).group - 1) * 12);
    if (/outgoing|extrovert|social|party|buli|chatty|gossip|flirt|impulsive/.test(candidateText)) score += 15;
    if (candidateSensei && yearDiff > 12 && relScore < 25) score -= 14;
  }

  if (isTeam && !isParty) {
    if (sharedTags.length) score += 24;
    if (ownStudent || hostOwnSensei) score += 20;
  }

  return score;
}

function contextualRoleplayCast(w, host, generatedCast, descriptor, options = {}) {
  if (!w || !host) return host ? [host.id] : [];

  /*
   * PRIVATE INVITE HARD GUARD
   *
   * A chatből / privát meghívásból létrejövő kettesben Eventet a setting
   * szövege SOHA nem minősítheti át csoportossá. Pl. "coffee after training"
   * tartalmazhatja a training szót, ettől még nem jelenhet meg random dojo-cast.
   * A forcePrivate magasabb prioritású minden descriptor-keywordnél.
   */
  if (options && options.forcePrivate === true) return [host.id];
  const explicitIds = new Set((Array.isArray(generatedCast) ? generatedCast : [])
    .map((id) => findChar(w, id))
    .filter((id) => id && id !== w.meId && id !== host.id && charById(w, id) && !isHuman(w, id)));

  const eventText = String(descriptor || "").toLowerCase();
  const isTraining = /\b(?:practice|training|dojo|karate|class|lesson|sparring|edz[eé]s|gyakorl[aá]s)\b/.test(eventText);
  const isParty = /\b(?:party|buli|cabin\s*party|house\s*party|bonfire|afterparty|club\s*night|h[aá]zibuli)\b/.test(eventText);
  const isTeam = /\b(?:meeting|briefing|mission|team|crew|squad|operation|work\s+meeting|munka|megbesz[eé]l[eé]s|küldet[eé]s|csapat)\b/.test(eventText);
  const isGroupSocial = /\b(?:group\s+hangout|everyone|everybody|friends\s+over|game\s+night|dinner\s+party|barbecue|bbq|közös\s+program|társaság|mindenkit)\b/.test(eventText);
  const detectedGroupEvent = isTraining || isParty || isTeam || isGroupSocial;
  const groupEvent = options && options.forceGroup === true ? true : detectedGroupEvent;

  /* Non-group event = player + host only. No random third wheel. */
  if (!groupEvent) return [host.id];

  const hostTags = roleplayAffiliationTags(host);
  const hostYear = roleplayBirthYear(host);
  const ranked = (w.chars || [])
    .filter((c) => c && c.id !== host.id && !isHuman(w, c.id))
    .map((c) => {
      const score = roleplayEventAudienceScore(w, host, c, eventText, explicitIds.has(c.id));
      const rel = getRel(w, host.id, c.id) || {};
      const bond = String(rel.bond || rel.type || "").toLowerCase();
      const shared = roleplayAffiliationTags(c).filter((tag) => hostTags.includes(tag));
      const ownStudent = isOwnSenseiRelationship(w, c.id, host.id);
      const hostOwnSensei = isOwnSenseiRelationship(w, host.id, c.id);
      const candidateSensei = characterIsSensei(c);
      const cy = roleplayBirthYear(c);
      const yearDiff = hostYear && cy ? Math.abs(hostYear - cy) : 99;
      const knownPersonally = Math.abs(Number(rel.score) || 0) >= 12 || Boolean(bond) ||
        socialInteractionInterest(w, host.id, c.id) >= 20 || Boolean(ownStorySnippetAbout(host, c));
      let contextFit = false;
      if (isTraining) {
        contextFit = ownStudent || hostOwnSensei ||
          (shared.length > 0 && (candidateSensei || /student|karate|fighter|coach|instructor|sensei|di[aá]k|harcos|edz[oő]/i.test([c.job,c.bio,c.extra].filter(Boolean).join(" "))));
      } else if (isParty) {
        contextFit = knownPersonally && (yearDiff <= 10 || /friend|best|close|partner|dating|rival|ally|bar[aá]t|sz[oö]vets/.test(bond) || characterOnlineActivityProfile(w, c).group >= 1.0);
      } else if (isTeam) {
        contextFit = shared.length > 0 || ownStudent || hostOwnSensei || (explicitIds.has(c.id) && knownPersonally);
      } else {
        contextFit = knownPersonally && explicitIds.has(c.id);
      }
      return { id: c.id, score, explicit: explicitIds.has(c.id), contextFit };
    })
    .filter((row) => row.contextFit)
    .sort((a, b) => (b.score - a.score) || String(a.id).localeCompare(String(b.id)));

  const maxCast = isTraining ? 10 : isParty ? 9 : isTeam ? 8 : 7;
  const selected = [host.id];
  ranked.forEach((row) => {
    if (selected.length >= maxCast) return;
    const threshold = isTraining ? 22 : isParty ? 24 : 20;
    if (row.explicit || row.score >= threshold) selected.push(row.id);
  });
  return [...new Set(selected)].filter(Boolean).slice(0, maxCast);
}

function roleplayRomanticInitiativeCard(w, scene, cast) {
  if (
    !w ||
    !scene ||
    worldContentLevel(w, w.meId) !== "mature"
  ) {
    return "";
  }

  const recentText =
    (scene.turns || [])
      .slice(-18)
      .map((t) => String(t && t.text || ""))
      .join(" ")
      .toLowerCase();

  const explicitBoundary = roleplayHasRecentExplicitPlayerBoundary(w, scene);

  if (explicitBoundary) {
    return `ROMANTIC INITIATIVE CHECK: the PLAYER has a recent, explicit intimacy boundary/refusal in their own last few turns. Do not escalate romance or intimacy until the player clearly changes that boundary. Do not infer a boundary merely from an unrelated word such as "no" in ordinary dialogue.`;
  }

  const player =
    charById(w, w.meId);

  const targets =
    [player, ...(cast || [])]
      .filter(Boolean);

  const rows = [];

  (cast || []).forEach((actor) => {
    if (!actor || isHuman(w, actor.id)) return;

    targets.forEach((target) => {
      if (
        !target ||
        target.id === actor.id ||
        !matureParticipantsAreAdults(
          w,
          [actor.id, target.id]
        )
      ) {
        return;
      }

      const rel =
        getRel(
          w,
          actor.id,
          target.id
        );

      const score =
        Number(rel && rel.score) || 0;

      const bond =
        String(rel && rel.bond || "")
          .toLowerCase();

      const lore =
        [
          actor.personality,
          actor.traits,
          actor.bio,
          actor.backstory,
          actor.extra,
          actor.goals,
          actor.likes,
        ]
          .filter(Boolean)
          .join(" ")
          .toLowerCase();

      let initiative = score;

      if (bondLooksRomantic(rel)) initiative += 46;
      if (/crush|dating|partner|girlfriend|boyfriend|lover|wife|husband|romance|attract|vonz|szerelm|intim/.test(bond)) initiative += 36;
      if (/flirt|bold|merész|dominant|domináns|impulsive|impulzív|passionate|szenvedély|possess|birtokl|obsess|megszáll|confident|magabiztos/.test(lore)) initiative += 18;
      if (/shy|félénk|reserved|visszafogott|avoidant|bizalmatlan/.test(lore)) initiative -= 12;
      if (/kiss|csók|making out|make out|csókolóz|desire|vágy|attraction|vonzalom|chemistry|kémia|flirt|flört/.test(recentText)) initiative += 18;
      const intimacyStage = roleplayAdultIntimacyStage(w, scene);
      if (intimacyStage === "kiss-touch") initiative += 10;
      if (intimacyStage === "mutual-kissing") initiative += 22;
      if (intimacyStage === "private-intimacy") initiative += 28;

      if (initiative >= 62) {
        rows.push({
          actor,
          target,
          initiative,
          score,
          bond,
        });
      }
    });
  });

  if (!rows.length) {
    return `ROMANTIC INITIATIVE CHECK: no currently strong, adult, canon-supported initiative candidate. Do not manufacture romance.`;
  }

  rows.sort((a, b) => b.initiative - a.initiative);
  const top = rows.slice(0, 4);
  const hasConcreteEscalation =
    /\b(?:kiss(?:ed|ing|es)?|making\s*out|make\s*out|cs[oó]k|cs[oó]kol|cs[oó]kol[oó]z|came\s+closer|moved\s+closer|meg[eé]rint|touch(?:ed|es|ing)?\s+(?:her|his|their|your)\s+(?:face|hand|waist))\b/i.test(
      recentText
    );

  const sustained =
    (scene.turns || []).length >= 4 &&
    !hasConcreteEscalation &&
    top[0].initiative >= 78;
  const intimacyStage = roleplayAdultIntimacyStage(w, scene);

  return `ROMANTIC / ADULT INITIATIVE CHECK — concrete, not decorative:\n${top.map((row) => `- ${row.actor.name} [${row.actor.id}] → ${row.target.name} [${row.target.id}]: initiative=${Math.round(row.initiative)}, relationship=${row.score}${row.bond ? `, bond=${row.bond}` : ""}`).join("\n")}\n- Current non-graphic intimacy stage inferred from ACTUAL recent turns: ${intimacyStage}.\n- These are opportunities, not obligations. Character, timing and consent still rule.\n- Do not endlessly describe chemistry while making every AI wait for the other person. An eligible bold/attracted AI may make the first concrete move.\n- If the scene is already at kiss-touch / mutual-kissing / private-intimacy and there is no recent explicit player boundary, DO NOT reset it back to coy small talk or another almost-kiss. Continue from the actual established physical/emotional state.\n- A concrete move can be closing distance, a deliberate touch, clearly attempting/initiating a kiss, intensifying mutually established kissing, asking the other adult somewhere private, or initiating/continuing a non-graphic transition toward adult intimacy.\n- If the player has already clearly reciprocated in an actual stored turn, the AI may respond to that reciprocity; still never invent the player's NEXT reaction.\n- Non-graphic adult intimacy may continue as a scene through dialogue, closeness, kissing, atmosphere and time progression; fade-to-black is optional, not mandatory. Never add graphic anatomical/pornographic detail.\n- If the target is the PLAYER, write only the AI's own next action/dialogue and stop before deciding the player's next choice.\n${sustained ? "- INITIATIVE DUE: this scene has sustained strong chemistry without a concrete move. If the current physical/social moment still supports it, at least one top eligible AI should advance the relationship with a real initiative THIS TURN instead of adding another round of unresolved tension." : "- Do not force a move this turn if the moment is genuinely wrong; however, do not make first-move behavior mechanically rare."}`;
}

